// Öğrenme yollarında anlama ve tedebbür katmanı.
// buyukResim: yola girmeden önce bütünü gösteren yazı · hedefler: yolun sonunda neyi anlamış olacağın
// etaplar: [başlık, ilk adım, son adım, bağlantı sorusu]
// adim[i]: { amac, odak (okumaya girerken akılda tutulacak soru), not (sayfada olmayan ilmî derinleşme), tedebbur: [[soru, düşünme yönü]] }
// sentez: yolun sonunda yazılacak düşünce yazısı
window.YOL_EK = {
  ihtilaf: {
    buyukResim: "Bu yol, mezheplerin farklı sonuçlara nasıl vardığını ezberletmek için değil, bir fakihin nasıl düşündüğünü görmek için hazırlandı. Önce ihtilafın sebeplerine dair bir harita ediniyorsun; sonra dört imamın her birinin bu haritada nerede durduğunu görüyorsun; ardından aynı sebeplerin beş farklı meselede nasıl iş gördüğünü izliyorsun. Yolun sonunda bir meseleye baktığında “kim ne demiş” sorusundan önce “ayrılık nereden doğuyor” sorusunu soruyor olmalısın.",
    hedefler: ["Bir fıkıh meselesinde görüşlerin arkasındaki usul farkını görebilmek.", "Dört imamın yöntemini birbirinden ayıran temel tercihi kendi cümlelerinle anlatabilmek.", "Farklı görüşlere, taassup yerine anlayışla yaklaşabilmek.", "Kendi mezhebinin görüşünü delil ve gerekçesiyle savunabilmek."],
    sure: "Yaklaşık 2 hafta; günde 1 adım", onbilgi: "Temel ibadet bilgisi yeterlidir.",
    etaplar: [["Çerçeve", 0, 0, ""], ["Dört imam, dört yöntem", 1, 4, "Dört imamı bir çizgi üzerine yerleştirsen, bir ucunda re'ye, diğer ucunda nassa en sıkı bağlılık olsa, her birini nereye koyardın? Bu sıralama her meselede aynı kalır mı?"], ["Usul farkları meselelerde", 5, 9, "Bu beş meselenin her birinde ayrılığın kaynağını tek kelimeyle adlandırmaya çalış. Hangileri aynı usul farkına dayanıyor?"], ["Karşılaştırmanın ustaları", 10, 11, "İbn Rüşd ve Dihlevî ihtilafa “dışarıdan” bakarken, mezhep imamları “içeriden” ictihad ediyordu. Bu iki bakış birbirini nasıl tamamlar?"]],
    adim: {
      0: { amac: "Yol boyunca kullanacağın ihtilaf sebepleri haritasını edinmek.", odak: "Aynı Kur'an'a ve sünnete bağlı âlimler nasıl olur da farklı sonuçlara varır?",
        not: "İbn Teymiyye, Ref'ü'l-melâm ani'l-eimmeti'l-a'lâm adlı risalesinde bir imamın sahih bir hadise aykırı görünen görüşünü üç ana mazerete bağlar: hadisin ona ulaşmamış olması, ulaştığı hâlde sahih olduğuna kanaat getirmemesi veya hadisin başka bir anlama geldiğini ya da neshedildiğini düşünmesi. Bu ayrım, bir âlimi suçlamadan önce sorulması gereken soruları gösterir.",
        tedebbur: [["Bir âlimin görüşü sana zayıf göründüğünde, onu eleştirmeden önce hangi soruları sormalısın?", "İbn Teymiyye'nin üç mazeretini bir kontrol listesi gibi düşün: Delil ona ulaştı mı? Delilin sıhhatini nasıl değerlendirdi? Delili nasıl anladı?"], ["İhtilaf her zaman bir zaaf mı, yoksa bazen bir zenginlik midir?", "Ömer b. Abdülazîz'in “Sahabenin ihtilaf etmemesi beni sevindirmezdi” sözünü ve bunun hangi tür ihtilaflar için geçerli olduğunu düşün."]] },
      1: { amac: "Re'y geleneğinin mantığını kavramak.", odak: "Ebû Hanîfe kıyası ve istihsânı neden bu kadar önemsedi?",
        not: "Ebû Hanîfe'nin delil sırası kendi ağzından şöyle nakledilir: “Allah'ın Kitabında bulursam onu alırım; bulamazsam Resûlullah'ın sünnetini alırım. Onda da bulamazsam sahabenin sözlerinden dilediğimi alırım, ama onların dışına çıkmam. İş İbrâhim, Şa'bî, İbn Sîrîn ve Atâ gibilere gelince, onlar ictihad etti, ben de ictihad ederim” (Hatîb, Târîhu Bağdâd). Bu söz, re'y ehlinin nassı ihmal ettiği iddiasına doğrudan bir cevaptır.",
        tedebbur: [["Ebû Hanîfe'nin sahabe ile tâbiûn arasında yaptığı ayrımın gerekçesi ne olabilir?", "Sahabenin Hz. Peygamber'i doğrudan görmüş olmasını, tâbiûnun ise kendisi gibi bir müctehid olmasını karşılaştır."], ["Kûfe'nin bir ticaret ve göç şehri olması, Ebû Hanîfe'nin henüz yaşanmamış meseleler için hüküm üretmesini nasıl açıklayabilir?", "Medine'deki görece sabit toplumla, farklı kültürlerin karıştığı Kûfe'nin karşılaştığı yeni meseleleri karşılaştır."]] },
      2: { amac: "Medine amelinin neden bir delil sayıldığını anlamak.", odak: "Bir şehrin uygulaması, tek bir hadisten daha güçlü olabilir mi?",
        not: "Kādî İyâz, Medine amelini ikiye ayırır: Nesilden nesile aktarılan nakli amel (ezanın şekli, sâ' ölçüsü, ezanın minareden okunması gibi) ve ictihada dayanan amel. Mâlikîlerin çoğuna göre birincisi kesin bir delildir, ikincisi ise diğer ictihadlar gibi tartışmaya açıktır. Leys b. Sa'd'ın itirazı esas olarak ikinci türe yöneliktir.",
        tedebbur: [["Kādî İyâz'ın yaptığı ayrım, Leys ile Mâlik arasındaki tartışmayı nasıl yumuşatır?", "Leys'in itirazının hangi tür amele yöneldiğini, Mâlik'in ise hangi türü savunduğunu düşün."], ["Bir toplumun yaşayan geleneği ile yazılı bir metin arasında çatışma olursa hangisi neden güvenilir olabilir?", "Ezan gibi her gün beş kez tekrarlanan bir uygulamanın tek bir ravi tarafından aktarılan bir haberle karşılaştırılmasını düşün."]] },
      3: { amac: "Usulün bir ilim olarak doğuşunu görmek.", odak: "Şâfiî'nin er-Risâle'si fıkha ne kazandırdı?",
        not: "Şâfiî, er-Risâle'de “beyân” kavramını merkeze alır: Allah'ın hükümlerini bildirme yolları farklı derecelerdedir. Bazı hükümler Kur'an'da açıkça bildirilmiş, bazıları Kur'an'da ana hatlarıyla bildirilip sünnetle açıklanmış, bazıları yalnızca sünnetle bildirilmiş, bazıları da ictihada bırakılmıştır. Böylece sünnet ile Kur'an arasındaki ilişki bir rekabet değil, bir beyân ilişkisi olarak kurulur.",
        tedebbur: [["Şâfiî'nin Mısır'da görüşlerinin önemli bir kısmını değiştirmesi, bir müctehidin tavrı hakkında sana ne söylüyor?", "Görüş değiştirmenin bir zaaf mı, yoksa delile bağlılığın göstergesi mi olduğunu düşün; “Hadis sahih olursa mezhebim odur” sözüyle birlikte değerlendir."], ["“Beyân” kavramı sünnet ile Kur'an arasındaki ilişkiyi neden bir rekabet olmaktan çıkarır?", "Sünnetin Kur'an'a neyi “ekleyebileceğini” değil, onu nasıl “açıkladığını” düşün."]] },
      4: { amac: "Ehl-i hadisin fıkıh anlayışını tanımak.", odak: "Ahmed b. Hanbel neden zayıf bir hadisi kıyasa tercih ederdi?",
        not: "İbn Teymiyye, Ahmed'in “zayıf hadisi kıyasa tercih ederim” sözündeki “zayıf” kelimesinin, sonraki dönemlerin “zayıf” kavramıyla aynı olmadığını söyler. Ahmed'in döneminde hadisler sahih ve zayıf olarak ikiye ayrılıyordu; Tirmizî'den sonra yerleşen “hasen” derecesi de “zayıf” kapsamındaydı. Yani Ahmed'in tercih ettiği şey, uydurma veya çok zayıf rivayet değil, sonraki terminolojide hasen sayılacak rivayetlerdi.",
        tedebbur: [["Bir terimin anlamının zamanla değişmesi, eski âlimlerin sözlerini okurken bizi nasıl yanıltabilir?", "Ahmed'in “zayıf” kelimesini ve Tirmizî'den sonra yerleşen “hasen” kategorisini karşılaştır."], ["Ahmed'in “Beni taklit etme, onların aldığı yerden al” sözü, mezhep taklidi hakkında ne söyler?", "Bir imamın kendi takipçilerine bile taklit yerine delile yönelmeyi öğütlemesinin anlamını düşün."]] },
      5: { amac: "Tek bir kelimenin iki anlamının nasıl iki farklı hükme yol açtığını görmek.", odak: "“Lâmestum” el ile dokunmak mı, yoksa cinsel ilişkinin kinâyesi mi?",
        not: "Bu meselenin arkasında bir usul kuralı daha vardır: Bir lafız aynı cümlede hem hakiki hem mecazi anlamında birlikte kullanılabilir mi? Şâfiîlere göre kullanılabilir; bu yüzden “lâmestum” hem el ile dokunmayı hem cinsel ilişkiyi kapsayabilir. Hanefîlere göre ise bir lafız aynı anda iki anlamda kullanılamaz; mecazi anlam kesinleşince hakiki anlam düşer. Böylece abdest meselesindeki ayrılık, bir kelimenin yorumundan çok, dilin nasıl işlediğine dair bir görüş farkına dayanır.",
        tedebbur: [["“İhtilaftan çıkmak müstehaptır” kaidesi hangi durumlarda faydalı, hangi durumlarda zorlayıcı olabilir?", "İhtiyatın bir ruhsatı veya bir sünneti ortadan kaldırdığı durumları düşün."], ["Nevevî'nin deve eti konusunda kendi mezhebi dışındaki bir görüşü güçlü bulması, bir mezhep âlimini nasıl bir tavra davet eder?", "Mezhebin görüşüyle amel etmek ile delil bakımından hangi görüşün güçlü olduğunu söylemek arasındaki farkı düşün."]] },
      6: { amac: "Genel lafzın daraltılması tartışmasını somut bir meselede izlemek.", odak: "Bir âyet ile sahih bir hadis çatışıyor gibi göründüğünde hangisi öne alınır?",
        not: "Hanefîlerin bu meseledeki tavrı, farz ile vacip arasındaki ayrımlarıyla birlikte okunmalıdır. Onlara göre namazda kıraatin farz olması kesin delile, “Kur'an'dan kolayınıza geleni okuyun” (Müzzemmil 20) âyetine dayanır. “Fâtiha'sız namaz olmaz” hadisi âhâd olduğu için Kitab'ın mutlak emrine bir şart ekleyemez, ama Fâtiha'yı vacip kılar. Haber-i vâhidle Kitab'a ziyade yapılmaz ilkesi, Hanefîlerin hadisi reddetmeden ona daha düşük bir derece vermesinin yoludur.",
        tedebbur: [["Mâlikî ve Hanbelîlerin sesli-gizli namaz ayrımı, iki delil grubunu nasıl uzlaştırır? Bu uzlaştırma ikna edici mi?", "A'râf 204'teki “dinleyin” emrinin gizli namazda nasıl uygulanabileceğini düşün."], ["Âmm lafzın kesin mi zannî mi olduğu sorusu, bu meselenin dışında hangi meseleleri etkiler?", "Bu sitedeki cem ve abdest meselelerine bak; aynı usul sorusunun izini sür."]] },
      7: { amac: "Kesin delil ile âhâd haberin ilişkisini görmek.", odak: "Namaz vakitleri kesin olarak belirlenmişse, cem hadisleri nasıl anlaşılmalı?",
        not: "Usulde “Olaylara dair fiil haberleri genellik ifade etmez” (vakāi'u'l-a'yân lâ umûme lehâ) diye bir kaide vardır. Bir sahabinin “Hz. Peygamber şöyle yaptı” diye anlattığı tek bir olay, o fiilin hangi şartlarda yapıldığını tam bildirmeyebilir: yağmur mu vardı, hastalık mı, başka bir ihtiyaç mı? Bu yüzden fiil bildiren bir hadisten genel bir ruhsat çıkarmak, söz bildiren bir hadisten çıkarmaktan daha temkinli yapılır. Cem tartışmasında İbn Abbâs rivayetini daraltanlar ile genişletenler arasındaki fark büyük ölçüde bu kaideye bakışla ilgilidir.",
        tedebbur: [["“Ümmetini sıkıntıya sokmamak istedi” ifadesi bir illet mi, yoksa bir hikmet mi? Bu ayrım hükmü nasıl değiştirir?", "İllet hükmü doğuran belirli bir vasıftır, hikmet ise hükmün amacıdır. Hangisinin genelleştirilebileceğini düşün."], ["İbn Mes'ûd'un “görmedim” demesi ile Enes'in “gördüm” demesi çatıştığında neden genellikle “gören” tercih edilir? Bunun istisnası olabilir mi?", "Bilgiye dayalı bir olumsuzlama ile bilgisizlikten doğan bir olumsuzlamayı karşılaştır."]] },
      8: { amac: "Hükmün lafzına mı yoksa amacına mı bakılacağı tartışmasını kavramak.", odak: "Fitrede belirtilen yiyecek maddeleri bir şekil şartı mı, yoksa o dönemin değer ölçüsü mü?",
        not: "Şâtıbî, el-Muvâfakāt'ta önemli bir ayrım yapar: İbadetlerde aslolan, gerekçesi akılla tam kavranamayan bir kulluk (ta'abbüd), âdetlerde (muâmelât) ise gerekçeye ve amaca bakmaktır. Fitre meselesindeki ihtilaf, büyük ölçüde fitrenin bu iki alandan hangisine daha yakın olduğu sorusudur: Bir ibadet mi, yoksa mali bir yardımlaşma mı?",
        tedebbur: [["Fitre bir ibadet mi, mali bir yardımlaşma mı? Bu soruya verdiğin cevap seni hangi görüşe götürür?", "Şâtıbî'nin ta'abbüd ve mana ayrımını fitreye uygula; kurbanla karşılaştır."], ["Muâviye'nin buğdayı değerine göre takdir etmesine Ebû Saîd'in itiraz etmesi, sahabe döneminde de lafız ve mana eğilimlerinin bulunduğunu nasıl gösterir?", "Bugünkü ihtilafın kökünün sahabe dönemine kadar uzandığını düşün."]] },
      9: { amac: "Sahabe uygulamasının delil değerini görmek.", odak: "Hz. Peygamber'in tek başına yaptığı bir şey ile sahabenin cemaatle oluşturduğu gelenek nasıl ilişkilendirilir?",
        not: "Hz. Ömer'in teravih için söylediği “Ne güzel bid'at!” sözü, bid'at kavramının iki farklı tanımının sınandığı bir yerdir. İzz b. Abdisselâm ve Nevevî gibi âlimler bu sözü bid'atın beş hükme ayrılabileceğine delil gösterir. Şâtıbî ise burada “bid'at” kelimesinin sözlük anlamında (yeni yapılan şey) kullanıldığını, teravihin aslının sünnette bulunduğu için gerçek anlamda bir bid'at olmadığını söyler.",
        tedebbur: [["Ömer'in sözündeki “bid'at” kelimesini Şâtıbî gibi sözlük anlamında mı, İzz b. Abdisselâm gibi terim anlamında mı okumak daha tutarlı?", "Teravihin Hz. Peygamber döneminde birkaç gece cemaatle kılındığını ve Ömer'in yaptığının bu aslı yeniden düzenlemek olduğunu düşün."], ["Rekât sayısının bir “ölçü” değil bir “uygulama tarzı” olduğu fikri, teravih tartışmasını nasıl değiştirir?", "İbn Teymiyye'nin kıyamın uzunluğu ile rekât sayısı arasında kurduğu dengeyi düşün."]] },
      10: { amac: "Karşılaştırmalı fıkhın yöntemini bir ustadan öğrenmek.", odak: "İbn Rüşd her meselede neyi arıyordu?",
        not: "İbn Rüşd, Bidâye'nin girişinde ihtilafın sebeplerini lafızlar ve deliller üzerinden sınıflandırır: lafzın âmm-hâs, müşterek (çok anlamlı), hakikat-mecaz olması; emir ve nehyin derecesi; delillerin çatışması; kıyasın kullanımı. Bu sınıflandırma, onun her meseledeki “sebebü'l-hilâf” tespitlerinin arka planıdır. Kitabının amacını da, müctehid olmak isteyene bir alet kazandırmak olarak açıklar.",
        tedebbur: [["İbn Rüşd'ün sınıflandırmasını bu yolda gördüğün beş meseleye uygula. Her mesele hangi kategoriye giriyor?", "Abdest: müşterek lafız; Fâtiha: âmm-hâs; cem: âhâd haber ile kesin delil; fitre: lafız-amaç; teravih: sahabe uygulaması."], ["Bir eserin amacının “müctehid yetiştirmek” olması, onu okuma şeklimizi nasıl değiştirmeli?", "Görüşlerin listesini öğrenmek ile o görüşleri üreten düşünme biçimini öğrenmek arasındaki farkı düşün."]] },
      11: { amac: "Mezheplere taassupsuz bakışı bir model üzerinden görmek.", odak: "Mezhebe bağlılık ile delile bağlılık nasıl bir arada olabilir?",
        not: "Dihlevî, el-İnsâf'ta 4. asırdan önce insanların tek bir mezhebe sıkı sıkıya bağlı olmadığını, bir meselede kime ulaşırsa onun fetvasıyla amel ettiğini tespit eder. Belirli bir mezhebe bağlılığın sonradan, ilmin korunması ve düzenin sağlanması gibi faydalar sebebiyle yerleştiğini söyler. Ona göre mezhep bağlılığı meşrudur, ancak sahih bir delilin açıkça başka bir yönü gösterdiği yerde taassup meşru değildir.",
        tedebbur: [["Dihlevî'nin tarihî tespiti, bugün bir mezhebe bağlı olmanın anlamını nasıl değiştirir?", "Mezhebin bir “ilim geleneği” ve “usul disiplini” olarak faydalarını, taassubun zararlarıyla karşılaştır."], ["Senin için mezhep bağlılığı ile delile bağlılık arasındaki denge nerede kuruluyor?", "Bu yolda gördüğün Nevevî, Leknevî ve İbnü'l-Kayyim örneklerini hatırla."]] }
    },
    sentez: "Bu yolda incelediğin meselelerden ikisini seç. Her biri için ihtilafın kaynağını tek cümleyle yaz, sonra iki meselenin aynı usul farkına dayanıp dayanmadığını açıkla. Son olarak kendi mezhebinin görüşünü bir arkadaşına delilleriyle anlatır gibi kısa bir paragraf yaz." },

  "son-sayfalar": {
    buyukResim: "Bu yol, her gün namazda okuduğun kısa surelerin anlamına inmen için hazırlandı. Amaç, her surenin ne dediğini öğrenmekle kalmayıp onun sana ne söylediğini fark etmek: tedebbür. Her adımda önce meali sesli oku, sonra akışı ve kavramları incele; derinleşme notunda o surenin bir dil inceliğine veya iniş ortamına bak; en sonda da tefekkür sorusu üzerinde birkaç dakika dur. O gün kıldığın namazlarda o sureyi oku ve anlamını düşün.",
    hedefler: ["Her surenin ana mesajını kendi hayatına bağlayarak anlatabilmek.", "Kısa surelerdeki dil inceliklerinin anlamı nasıl derinleştirdiğini fark edebilmek.", "Bu sureleri namazda anlamını düşünerek okuyabilmek."],
    sure: "12 gün; her gün bir sure", onbilgi: "Gerekmez.",
    etaplar: [["Namazın kapısı ve teselli", 0, 2, "Fâtiha'daki “sana kulluk ederiz” ahdi ile Duhâ ve İnşirâh'taki teselli arasında nasıl bir bağ var? Kulluğun karşılığında ne vaat ediliyor?"], ["Zaman, çokluk ve ibadet", 3, 5, "Asr zamanı, Tekâsür çokluk yarışını, Mâûn ise ibadetin ahlâkını konu ediniyor. Üçünü birleştiren insan zaafı nedir?"], ["Bolluk, sadakat ve zafer", 6, 8, "Kevser'de bolluk, Kâfirûn'da baskı, Nasr'da zafer var. Her durumda Peygamber'den istenen tavır ne?"], ["Tevhid ve sığınma", 9, 11, "İhlâs Allah'ı tanıtıyor, Felak ve Nâs O'na sığınmayı öğretiyor. Allah'ı doğru tanımak ile O'na doğru sığınmak arasındaki ilişki ne?"]],
    adim: {
      0: { amac: "Her namazda okuduğun duayı anlayarak okumak.", odak: "Fâtiha'da “sana kulluk ederiz” cümlesinden önce ve sonra ne söylenir?",
        not: "Fâtiha'nın isimlerinden biri “Rukye”dir. Ebû Saîd el-Hudrî'nin anlattığına göre, bir yolculukta akrep sokan bir kabile reisine sahabeden biri Fâtiha okumuş ve adam iyileşmiştir. Hz. Peygamber “Onun bir rukye (şifa duası) olduğunu nereden bildin?” diye sormuştur (Buhârî, Müslim). Ayrıca dikkat çekici bir soru vardır: Zaten hidayette olan mümin neden her rekâtta “Bizi doğru yola ilet” der? Müfessirler cevap verir: Hidayet bir kez verilip biten bir şey değildir; istenen, o yolda sebat ve her gün biraz daha ilerlemektir.",
        tedebbur: [["Namazda Fâtiha'yı okurken, üçüncü şahıstan “sana” diye hitaba geçtiğin anı fark ediyor musun? Bu geçiş sende neyi değiştirebilir?", "Bir yöneticiden söz ederken birden onun huzuruna çıkıp onunla konuşmaya başlamayı düşün."], ["Neden önce “kulluk ederiz”, sonra “yardım dileriz” deniyor?", "Kulluğun yardım istemenin ön şartı mı, yoksa kulluğun kendisinin de yardıma muhtaç olduğunu mu gösterdiğini düşün."]] },
      1: { amac: "Terk edilmişlik duygusuna karşı Kur'an'ın tesellisini hissetmek.", odak: "Rabbin seni terk etmediğini sana hangi geçmiş nimetler hatırlatıyor?",
        not: "Üçüncü âyette “Rabbin seni bırakmadı (mâ vedde'ake) ve sana darılmadı (ve mâ kalâ)” denir. Dikkat edilirse ilk fiilde “seni” zamiri vardır, ikincisinde ise yoktur. Râzî gibi müfessirler bunu bir nezaket inceliği olarak açıklar: “Sana darılmadı” derken bile Hz. Peygamber'e doğrudan “sana” denmekten kaçınılmıştır. Sure, terk edilmişlik korkusunu böyle bir şefkat diliyle karşılar.",
        tedebbur: [["Surenin ortasında üç geçmiş nimet (yetim iken barındırılmak, yol bulamazken yol gösterilmek, fakir iken zengin edilmek) hatırlatılıyor. Senin hayatında bu üçe karşılık gelen anlar neler?", "Geçmişte Allah'ın seni koruduğu anları hatırlamanın şimdiki kaygıya nasıl ilaç olduğunu düşün."], ["Surenin son üç emri neden yetim, isteyen ve nimetle ilgili?", "Bu üç emrin, hatırlatılan üç geçmiş nimetin ayna karşılığı olduğunu fark et."]] },
      2: { amac: "Zorlukla kolaylığın birlikteliğini kavramak.", odak: "Kolaylık zorluktan “sonra” mı, zorlukla “beraber” mi?",
        not: "Sure, “Senin göğsünü açmadık mı?” sorusuyla başlar. Belâgatte buna “takrîrî istifham” denir: Cevabı bilinen bir soru, muhatabın onu kendi ağzıyla onaylaması için sorulur. Yani anlam “Elbette açtık”tır, ama soru kalıbı insanı kendi hayatına bakıp bunu bizzat görmeye davet eder. Duhâ ile bu sure arasındaki bağ o kadar sıkıdır ki Tâvûs ve Ömer b. Abdülazîz gibi bazı selef âlimlerinin ikisini tek sure saydığı ve bir rekâtta birlikte okuduğu nakledilir; ancak Mushaf'taki tertip ve cumhurun görüşü ikisinin ayrı sureler olduğu yönündedir.",
        tedebbur: [["Şu an yaşadığın bir zorluğun “içinde” saklı kolaylık ne olabilir?", "Âyetin “sonra” değil “beraber” dediğini hatırla; kolaylığı gelecekte değil şimdide ara."], ["Surenin sonunda “Bir işi bitirince diğerine koyul” denmesi, teselliden sonra neden geliyor?", "Tesellinin insanı rehavete değil yeni bir çabaya yönelttiğini düşün."]] },
      3: { amac: "Zamanın ve kurtuluşun dört şartını özümsemek.", odak: "Hüsrandan kurtulanlar hangi dört vasfı taşır?",
        not: "İkinci âyetteki “el-insân” kelimesinin başındaki belirlilik takısı, belirli bir insanı değil, insan cinsinin tamamını kapsar. Böylece bütün insanlık hüsranda gösterilir ve kurtulanlar istisna olarak ayrılır. Kurtuluşun ilk iki şartı (iman ve salih amel) bireysel, son iki şartı (hakkı ve sabrı tavsiye etmek) ise toplumsaldır. İnsanın yalnızca kendini kurtarmasının yeterli olmadığı, birbirini hakka ve sabra çağıran bir topluluğun parçası olması gerektiği anlatılır.",
        tedebbur: [["Kurtuluşun yarısının toplumsal olması sana ne söylüyor? Senin “hakkı ve sabrı tavsiye ettiğin” bir çevren var mı?", "İman ve amel bireysel kalırsa ne eksik kalır, düşün."], ["Allah'ın zamana yemin etmesi, zamanı nasıl kullandığına bakışını nasıl değiştirebilir?", "Zamanın hem bir sermaye hem de geri dönüşü olmayan bir kayıp olduğunu düşün."]] },
      4: { amac: "Çokluk yarışının insanı nasıl oyaladığını fark etmek.", odak: "Hayatımda neyi “çoğaltma” yarışındayım?",
        not: "İkinci âyette ölüm, “kabirleri ziyaret etmek” olarak ifade edilir. Müfessirler “ziyaret” kelimesinin bir geçicilik bildirdiğine dikkat çeker: Ziyaretçi kalıcı değildir. Böylece kabrin de son durak olmadığı, ardından dirilişin geleceği ima edilir. Üçüncü ve dördüncü âyetlerde “Hayır, yakında bileceksiniz” uyarısının iki kez tekrarlanması ise, bir kez kabirde, bir kez âhirette bilineceği şeklinde yorumlanmıştır.",
        tedebbur: [["Çokluk yarışı yalnız mal mıdır? Sen hangi “çokluk” yarışındasın: takipçi, unvan, bilgi, eşya?", "Âyetin yarışılan şeyi belirtmediğini, bunun her çağa açık kaldığını düşün."], ["Son âyetteki “nimetten sorulmak”, sıradan nimetlere (su, gölge, sağlık) bakışını nasıl değiştirmeli?", "Hz. Peygamber'in hurma ve soğuk su ikramından sonra bu âyeti hatırlattığı rivayeti düşün."]] },
      5: { amac: "İbadet ile ahlâkın ayrılmazlığını görmek.", odak: "Namaz kılan biri nasıl “vay haline” uyarısına muhatap olur?",
        not: "Müfessirler bu surenin nerede indiği konusunda ayrılmıştır. Bazıları tamamını Mekkî sayar. Bazıları ise ilk üç âyetin Mekke'de, yetimi iten bir müşrik hakkında; son dört âyetin Medine'de, namazı gösteriş için kılan münafıklar hakkında indiğini söyler. Bu görüş kabul edilirse sure iki ayrı portreyi yan yana koyar: Dini açıkça yalanlayan kişi ile dini dışarıdan yaşayıp içini boşaltan kişi. İkisinin de ortak noktası, yardıma muhtaç olana sırt çevirmektir.",
        tedebbur: [["Sure dini yalanlamayı inançla değil, yetime ve yoksula karşı davranışla tanımlıyor. Bu, dinin ne olduğu hakkında ne söylüyor?", "İnanç ile ahlâkın ayrılmaz olduğunu ve davranışın inancın aynası olduğunu düşün."], ["“Mâûn”, yani en küçük yardımı (bir kap, bir alet) esirgemek neden bu kadar ağır bir uyarıyla anılıyor?", "Büyük fedakârlıklardan önce küçük cömertliğin bir karakter göstergesi olduğunu düşün."]] },
      6: { amac: "Bolluğun karşılığının şükür ve kulluk olduğunu kavramak.", odak: "Kevser'e karşılık hangi iki şey emredilir?",
        not: "Sure “Biz sana verdik” (innâ a'taynâke) diye geçmiş zamanla başlar: Vaat edilen bir şey değil, verilmiş ve kesinleşmiş bir nimettir. Ardından gelen “fe” (o hâlde) edatı, namaz ve kurban emrini bu nimetin doğal bir sonucu olarak bağlar. “Rabbin için” kaydı ise, müşriklerin kurbanlarını putlar adına kestiği bir ortamda ibadetin yalnız Allah'a yöneltilmesini vurgular. Böylece en kısa sure, nimet, şükür ve ihlası üç âyette birleştirir.",
        tedebbur: [["Sana verilen “çok hayır” neler? Bunlara karşılık namaz ve kurban gibi bir kulluk ifaden var mı?", "Bolluğun bir şükür ve kulluk çağrısı olduğunu düşün."], ["Düşmanın “soyu kesik” sözüne Kur'an'ın cevabı, değerin neyle ölçüldüğü hakkında ne söylüyor?", "Hz. Peygamber'in adının bugün nasıl anıldığını ve o düşmanın adının neredeyse unutulduğunu düşün."]] },
      7: { amac: "İnançta netliğin ve farklılığa saygının sınırını öğrenmek.", odak: "“Sizin dininiz size, benim dinim bana” bir uzlaşma mı, bir ayrılık ilanı mı?",
        not: "Bazı âlimler bu surenin, özellikle son âyetinin, daha sonra inen savaş âyetleriyle neshedildiğini ileri sürmüştür. Muhakkik müfessirler bu görüşe karşı çıkar: Sure bir emir değil, bir haber ve bir berâet (beri olma) ilanıdır; haberler neshedilmez. “Sizin dininiz size, benim dinim bana” cümlesi, bir taviz değil bir ayrışma bildirir; bu ayrışma ise her dönemde geçerlidir. Tartışma, bir âyetin türünü (emir mi, haber mi) tespit etmenin hüküm üzerindeki etkisini gösterir.",
        tedebbur: [["İnançta netlik ile farklı inançtakilere saygı nasıl bir arada bulunabilir?", "Sure ibadette taviz vermemeyi, son âyet ise bir arada yaşamayı düşünür; ikisini dengele."], ["Hayatında, değerlerinden “bir yıl sen, bir yıl ben” türünden bir pazarlık teklifiyle karşılaştığın oldu mu?", "Küçük tavizlerin zamanla nasıl büyüdüğünü düşün."]] },
      8: { amac: "Başarı anında takınılacak tavrı öğrenmek.", odak: "Zafer gelince insan neyi artırmalıdır?",
        not: "İbn Abbâs'tan, tam olarak inen son surenin Nasr olduğu rivayet edilir (Müslim). Sure, insanların “bölük bölük” Allah'ın dinine girdiğini haber verir. Mekke'nin fethinden sonraki yıl (h. 9), Arap kabilelerinin heyetler hâlinde Medine'ye gelip İslâm'ı kabul ettiği için “heyetler yılı” (âmü'l-vüfûd) olarak anılır. Böylece sure, yirmi üç yıllık bir davetin meyvesini gösterirken, aynı anda o davetin sahibine görevinin bittiğini de haber verir.",
        tedebbur: [["Zafer anında istiğfar emredilmesi neden anlamlıdır? Başarı anında insan hangi hatalara düşebilir?", "Başarının kibir, gaflet ve haksızlık gibi tehlikeler taşıdığını düşün."], ["Bir görevin tamamlanması neden bir veda işaretidir?", "Hayatındaki büyük bir işi bitirdiğinde ne hissettiğini ve bunun bir son mu yoksa yeni bir başlangıç mı olduğunu düşün."]] },
      9: { amac: "Tevhidin özünü dört âyette kavramak.", odak: "İhlâs suresi Allah'ı neyle tanımlar, neyi O'ndan uzak tutar?",
        not: "Hz. Âişe'nin anlattığına göre Hz. Peygamber bir sahabiyi bir seriyyenin başına göndermişti. Bu sahabi, arkadaşlarına namaz kıldırırken her okuyuşunu İhlâs suresiyle bitiriyordu. Dönüşte durum Hz. Peygamber'e anlatılınca, “Ona sorun, bunu neden yapıyor?” buyurdu. Sahabi “Çünkü o Rahmân'ın sıfatıdır, onu okumayı seviyorum” dedi. Hz. Peygamber de “Ona, Allah'ın da onu sevdiğini haber verin” buyurdu (Buhârî, Müslim). İhlâs'ı sevmek, Allah'ı tanıtan sözü sevmektir.",
        tedebbur: [["Hayatında “samed”e, yani her ihtiyacında yöneldiğin şeye bak. Gerçekten yalnız Allah'a mı yöneliyorsun?", "İhtiyaç anında ilk aklına gelen kişi veya şeyin kalbindeki yerini düşün."], ["İhlâs suresinin Kur'an'ın üçte birine denk olması nasıl anlaşılabilir?", "Kur'an'ın ana konularını (tevhid, ahkâm, kıssalar ve âhiret gibi) düşün; tevhidin bunlar arasındaki yerini değerlendir."]] },
      10: { amac: "Dışarıdan gelen şerlere karşı Allah'a sığınmayı öğrenmek.", odak: "Felak'ta hangi dört şerden sığınılır?",
        not: "İkinci âyette “yarattığı şeylerin şerrinden” denir; şer, yaratılmışlara nispet edilir, Allah'a değil. Kelâma göre hayrı da şerri de yaratan Allah'tır; ama edep, şerri O'na nispet etmemeyi gerektirir. Hz. Peygamber'in gece namazının başında okuduğu duada “Hayrın tamamı senin elindedir, şer ise sana nispet edilmez” (ve'ş-şerru leyse ileyk) buyurduğu nakledilir (Müslim). Fâtiha'da “nimet verdiklerin” denip, gazap edilenlerde faili anılmayan edilgen yapı kullanılması da aynı edebin bir örneğidir.",
        tedebbur: [["Karanlığı yaran Rabbe sığınmak, korkuların karşısında sana ne hissettiriyor?", "Her karanlığın bir sabahla yarıldığını, korkunun da kalıcı olmadığını düşün."], ["Hasedin şerrinden sığınmak, kendi kalbindeki haset için de bir uyarı olabilir mi?", "Hasede uğramak kadar haset etmenin de bir şer olduğunu düşün."]] },
      11: { amac: "İçten gelen vesveselere karşı sığınmayı öğrenmek.", odak: "Nâs suresinde Allah hangi üç sıfatla anılır?",
        not: "Son âyet, vesvese verenin “cinlerden ve insanlardan” olduğunu söyler. En'âm 112 de “insan ve cin şeytanları”ndan söz eder: İnsan da bir başkasının kalbine şüphe ve kötülük fısıldayan bir şeytan rolüne girebilir. İbnü'l-Kayyim ayrıca şuna dikkat çeker: Felak'ta Allah'ın tek bir sıfatıyla dört ayrı şerden sığınılırken, Nâs'ta üç sıfatıyla tek bir şerden sığınılır. Çünkü vesvesenin zararı dine, diğerlerinin zararı ise bedene ve dünyaya yöneliktir; dinî zarar daha büyük olduğu için ona karşı daha güçlü bir sığınma öğretilir.",
        tedebbur: [["Vesvesenin “hannâs”, yani zikirle geri çekilen olması, ona karşı nasıl bir yol gösteriyor?", "Vesveseyle tartışmak yerine Allah'ı anmanın neden daha etkili olduğunu düşün."], ["Felak dış şerlerden, Nâs iç şerlerden sığınmayı öğretiyor. Senin için hangisi daha çetin?", "Dışarıdan gelen bir zarar ile insanın kendi içindeki fısıltıyı karşılaştır."]] }
    },
    sentez: "On iki surenin her biri için bir cümlelik mesajını yaz. Sonra bunlardan birini seç ve bu hafta hangi namazında onu anlamını düşünerek okuyacağını, o surenin hayatında neye dokunduğunu kısa bir paragrafla anlat." },

  inanc: {
    buyukResim: "Bu yol, inancın en çok soru doğuran konularını bir “cevap listesi” olarak değil, bir düşünce tarihi olarak okumak için hazırlandı. Önce Ehl-i sünnetin iki büyük kelâm ekolünü tanıyorsun. Sonra kader, Allah'ın sıfatları ve ölümden sonrası gibi meselelerde bu ekollerin ve eleştirmenlerinin nasıl düşündüğünü izliyorsun. En sonda da bu tartışmaları bir klasik metinde ve iki büyük düşünürde toplu olarak görüyorsun. Amaç, hazır cevapları ezberlemek değil, cevapların hangi sorulara ve hangi delillere dayandığını anlamak.",
    hedefler: ["Eş'arî ve Mâtürîdî ekollerinin farkını, gerekçeleriyle birlikte kavrayabilmek.", "Kader ve sıfatlar gibi meselelerde aşırılıklardan nasıl korunulduğunu anlayabilmek.", "Âhâd haber ile itikad ilişkisini somut meselelerde değerlendirebilmek.", "Kendi inancını delilleriyle ve tartışmanın tarihini bilerek ifade edebilmek."],
    sure: "Yaklaşık 2-3 hafta", onbilgi: "İman esaslarının temel bilgisi.",
    etaplar: [["İki büyük ekol", 0, 1, "Eş'arî ile Mâtürîdî'nin aklın değeri konusundaki farkı, sonraki meselelerde hangi farklılıklara yol açacak?"], ["Kader ve irade", 2, 3, "Kesb ile cüz'î irade arasındaki fark, senin günlük sorumluluk duygunda bir fark yaratır mı?"], ["Allah'ı tanımak", 4, 6, "Tenzîh ile isbât arasındaki dengeyi kader meselesindeki dengeyle karşılaştır. Ehl-i sünnet her iki meselede de nasıl bir “orta yol” arıyor?"], ["Ölümden sonrası", 7, 9, "Kabir, şefaat ve mehdi meselelerinde âhâd haberin değeri nasıl farklı sonuçlara yol açtı? Üç meseleyi delil gücü bakımından sırala."], ["Metin ve büyük düşünürler", 10, 12, "Nesefî'nin özlü metni, Gazâlî'nin kalbe yönelişi ve İbn Teymiyye'nin akıl-nakil tezi: Bunlar aynı soruya verilmiş üç farklı cevap mı, yoksa birbirini tamamlayan üç yaklaşım mı?"]],
    adim: {
      0: { amac: "Eş'arî ekolünün doğuşunu ve kelâmın Ehl-i sünnet savunmasındaki rolünü görmek.", odak: "Bir Mu'tezilî neden Ehl-i sünnetin savunucusu oldu?",
        not: "Kaynaklarda Eş'arî'nin hocası Cübbâî'ye sorduğu bir soru nakledilir: Biri mümin olarak ölen, biri kâfir olarak ölen, biri de çocukken ölen üç kardeş düşünelim. Mu'tezile'ye göre Allah her kul için en iyi olanı (aslah) yapmak zorundadır. Çocuk “Beni neden büyütmedin ki ben de iman edip derecemi yükselteyim?” diye sorarsa, Allah “Büyüseydin kâfir olacaktın” diyecektir. O zaman kâfir olan kardeş de “Beni neden çocukken öldürmedin?” diye soracaktır. Bu tartışma, Allah'ın fiillerini insan aklının “en iyi” ölçüsüne bağlamanın zorluklarını gösterir.",
        tedebbur: [["“Üç kardeş” tartışması, Allah'ın fiillerini insan aklıyla sorgulamanın sınırı hakkında ne söylüyor?", "Aklın Allah'ın fiillerindeki hikmeti her zaman kavrayamayacağını, ancak bunun hikmetin olmadığı anlamına gelmediğini düşün."], ["Kelâmın akıl yürütme yöntemini Ehl-i sünnet akidesini savunmak için kullanmak bir çelişki mi, bir ihtiyaç mı?", "Eş'arî'nin İstihsânü'l-havz fi'l-kelâm risalesindeki savunmayı ve dönemin şartlarını düşün."]] },
      1: { amac: "Mâtürîdî ekolünün akla verdiği yeri kavramak.", odak: "Mâtürîdî'ye göre akıl, vahiy gelmeden ne bilebilir?",
        not: "Mâtürîdî, Kitâbü't-Tevhîd'e doğrudan Allah'tan söz ederek değil, bilginin kaynaklarından söz ederek başlar: duyular, doğru haber ve akıl. Önce insanın neyi nasıl bilebileceğini sağlamlaştırır, sonra Allah'ın varlığına ve birliğine geçer. Bu, kelâmın bir bilgi teorisi üzerine kurulmasının ilk sistemli örneklerinden biridir. Sonraki Nesefî Akāid'i de “Eşyanın hakikatleri sabittir” cümlesiyle, yani bilginin mümkün olduğunu ilan ederek başlar.",
        tedebbur: [["Allah'ı tanımaya, “Neyi nasıl bilebilirim?” sorusuyla başlamanın avantajı nedir?", "Şüpheci bir muhatapla konuşurken önce bilginin imkânını göstermenin neden gerekli olduğunu düşün."], ["Ebû Hanîfe'nin “Allah hiç peygamber göndermeseydi bile, akıl sahiplerinin O'nu tanıması gerekirdi” sözü insanın sorumluluğu hakkında ne söylüyor?", "Fıtrat kavramını ve peygamber gelmeyen toplulukların durumunu düşün."]] },
      2: { amac: "Kader tartışmasının iki grup âyetin birlikte okunması olduğunu görmek.", odak: "Allah her şeyi yaratıyorsa insan neden sorumludur?",
        not: "İmam Tahâvî, Ehl-i sünnetin ortak akide metinlerinden biri sayılan el-Akîde'sinde şöyle der: “Kaderin aslı, Allah'ın yarattıkları hakkındaki sırrıdır. Ona ne yakın bir melek ne de gönderilmiş bir peygamber muttali olmuştur. Bu konuda derinlemesine dalmak ve düşünmek, hüsrana götüren bir yoldur.” Bu söz, kader hakkında düşünmeyi yasaklamaz; ama kaderin “nasıl”ını çözmeye çalışmak ile ona iman edip sorumluluğu üstlenmek arasında bir sınır çizer.",
        tedebbur: [["Kaderi bir “mazeret” olarak kullanmak ile bir “teselli” olarak kullanmak arasındaki farkı kendi hayatından bir örnekle açıkla.", "Bir hata yaptığında “kaderim buymuş” demek ile başına gelen bir musibet karşısında aynı şeyi söylemek arasındaki farkı düşün."], ["Hz. Peygamber'in “Amel edin, herkese yaratıldığı şey kolaylaştırılır” cevabı, kader bilgisinin insanı neye yöneltmesi gerektiğini gösteriyor?", "Kaderin bilinmezliğinin insanı tembelliğe değil, amele yönelttiğini düşün."]] },
      3: { amac: "İki ekolün anahtar kavramlarını derinlemesine ayırt etmek.", odak: "Kesb ile cüz'î irade arasındaki fark nedir?",
        not: "Bu tartışmaya bir filozof-fakihin bakışı da ışık tutar. İbn Rüşd, el-Keşf an menâhici'l-edille adlı eserinde, cebir ile Mu'tezile'nin görüşü arasında bir orta yol önerir: Allah insanda fiil işleme gücü yaratmıştır; ama bir fiilin gerçekleşmesi, insanın bu gücü ile Allah'ın dışarıda yarattığı sebeplerin uyumuna bağlıdır. İnsan dilediğini yapmak ister, fakat bu isteğin gerçekleşmesi, kendi elinde olmayan bir düzenin içinde mümkün olur. Böylece hem insanın gerçek bir payı hem de her şeyin Allah'ın takdiri içinde olması korunur.",
        tedebbur: [["Said Nursi'nin “itibarî emir” açıklaması, kulun hem sorumlu hem de yaratıcı olmaması sorununu nasıl çözüyor?", "Bir düğmeye basmayı seçmen ile o düğmenin ışığı yakan sistemi yaratman arasındaki farkı düşün."], ["Eş'arî kesbine yöneltilen “cebre yakınlık” eleştirisi haklı mı?", "Kulun kudretinin fiilde gerçek bir etkisi yoksa sorumluluğun neye dayandığını sorgula."]] },
      4: { amac: "Tevhidin özünü kısa bir surede görmek.", odak: "İhlâs suresi hangi yanlış inançları reddeder?",
        not: "Kelâmcılar tevhidi Kur'an'daki bir âyetle ispat eder: “Eğer yerde ve gökte Allah'tan başka ilahlar olsaydı, ikisinin de düzeni bozulurdu” (Enbiyâ 22). Buna “burhân-ı temânu'” (karşılıklı engelleme delili) denir: İki ilah olsaydı, birinin bir şeyi dilediğinde diğerinin onu engelleyip engelleyemeyeceği sorusu, ya ikisinin de âciz olduğu ya da birinin gerçekte ilah olmadığı sonucuna varır. Kâinattaki düzen, tek bir iradenin işaretidir.",
        tedebbur: [["Kâinattaki düzenin birliği, Allah'ın birliğinin nasıl bir delili olabilir?", "Bir orkestrada iki şefin aynı anda farklı yönler verdiği bir durumu düşün."], ["İhlâs suresinin reddettiği “doğurmak” ve “doğmak”, Allah'ın sınırsızlığıyla neden bağdaşmaz?", "Doğmanın bir başlangıç, doğurmanın ise bir bölünme ve ihtiyaç gerektirdiğini düşün."]] },
      5: { amac: "Allah hakkında konuşurken iki aşırılıktan sakınmayı öğrenmek.", odak: "Tenzîh ile teşbîh arasındaki denge nasıl kurulur?",
        not: "Gazâlî, İlcâmü'l-avâm'da, Allah'ın sıfatlarına dair nasslarla karşılaşan sıradan bir müminin yedi görevi olduğunu söyler: Allah'ı her eksiklikten uzak tutmak (takdis), nassı tasdik etmek, manasını bilmediğini itiraf etmek (aczini kabul), susmak, kurcalamamak, kalbinde bile bu konuda tasarrufta bulunmamak ve ehline teslim olmak. Bu liste, iman ile merak arasında sağlıklı bir sınır çizer.",
        tedebbur: [["Gazâlî'nin yedi görevi, merakı tamamen yasaklıyor mu, yoksa onu yönlendiriyor mu?", "“Ehline teslim olmak” görevinin, araştırmanın kendisini değil, ehliyetsiz kurcalamayı sınırladığını düşün."], ["Günlük dilde kullandığımız “Allah her yerdedir” ifadesi hangi açıdan teşbihe kayabilir? Nasıl daha doğru söylenebilir?", "Mekânın bir yaratılmış olduğunu ve Allah'ın ilmi ile kudretinin her şeyi kuşattığını düşün."]] },
      6: { amac: "Haberî sıfatlar konusundaki üç yolu ayırt etmek.", odak: "“Allah'ın eli” ifadesi nasıl anlaşılmalıdır?",
        not: "Bu tartışmanın ilginç bir yönü, Hanbelî mezhebinin içinden de teşbihe karşı güçlü bir eleştirinin gelmesidir. Hanbelî âlim İbnü'l-Cevzî, Def'u şübehi't-teşbîh adlı eserinde, bazı Hanbelîlerin haberî sıfatları zahirine göre anlayarak Allah'ı yaratılmışlara benzettiğini söyler ve bunun Ahmed b. Hanbel'in yoluna aykırı olduğunu savunur. Bu eser, tartışmanın mezhepler arasında değil, her mezhebin içinde de yaşandığını gösterir.",
        tedebbur: [["“es-Selef eslem, el-halef ahkem” formülü iki yolu da meşru kabul ederken İbn Teymiyye neden buna karşı çıkıyor?", "Formülün selefi “bilgisiz ama güvende”, haleften olanları “bilgili ama riskli” gösterdiğini fark et."], ["Cüveynî'nin hayatının sonunda te'vîlden tefvîze dönmesi neyi düşündürüyor?", "Bir âlimin ömrünün sonunda kendi yöntemini yeniden değerlendirmesinin anlamını düşün."]] },
      7: { amac: "Berzah âlemine dair Ehl-i sünnet inancını delilleriyle kavramak.", odak: "Kabir azabı Kur'an'da geçer mi?",
        not: "“Berzah” kelimesi Kur'an'da üç yerde geçer. Rahmân 19-20'de ve Furkān 53'te, birbirine karışmayan iki deniz arasındaki engeli anlatır. Mü'minûn 100'de ise ölüm ile diriliş arasındaki âlemi. Kelimenin bu kullanımı, berzahın ne dünya ne de âhiret olduğunu, ikisi arasında kendine has yasaları olan bir ara âlem olduğunu gösterir. İki deniz yan yana durup birbirine karışmadığı gibi, berzah âlemi de dünyaya bitişik ama ondan ayrı bir gerçekliktir.",
        tedebbur: [["Uyku ile berzah arasında kurulan benzetme, gaybî bir gerçeği anlamamıza nasıl yardım eder ve sınırı nedir?", "Rüyada yaşananın dışarıdan görülmemesini, ama yaşayan için gerçek olmasını düşün."], ["Âhâd haberlerin toplamının “manevî tevâtür”e ulaşması ne demektir? Bir inanç için yeterli midir?", "Farklı lafızlarla aynı manayı anlatan çok sayıda rivayetin ortak çekirdeğini düşün."]] },
      8: { amac: "Şefaat konusunda Ehl-i sünnet ile Mu'tezile'nin ayrılığını kavramak.", odak: "Şefaat büyük günah sahiplerini kapsar mı?",
        not: "Arapçada “şefaat” kelimesi, “tek olanı çift yapmak” anlamındaki “şef'” kökünden gelir. Şefaat eden, şefaat edilenin yanına katılan ikinci kişidir. Bazı âlimler bu kök anlamdan ince bir sonuç çıkarır: Şefaat, hiçbir şeyi olmayana değil, elinde zayıf da olsa bir “tek” bulunana, yani imana sahip olana yapılır. Şefaatçi, eksik olanı tamamlar; yoktan bir şey yaratmaz. Bu yüzden şefaat ümidi, imanı ve ameli küçümsemeye değil, onları korumaya çağırır.",
        tedebbur: [["Şefaat inancı insanı günaha karşı gevşetebilir mi, yoksa daha sorumlu bir hayata mı yöneltir?", "Şefaatin Allah'ın izniyle ve rahmetinin bir tecellisi olduğunu, kesin bir “garanti” olmadığını düşün."], ["İbn Teymiyye ile Sübkî arasındaki asıl ayrılık noktası nedir: delil mi, yoksa tevhidin korunması kaygısı mı?", "Her iki tarafın da tevhidi korumak istediğini, ancak tehlikeyi farklı yerlerde gördüğünü düşün."]] },
      9: { amac: "Rivayet tenkidini ve tarihî bağlamı bir akide meselesinde uygulamak.", odak: "Mehdi inancı iman esaslarından mıdır?",
        not: "“Mehdi” kelimesi sözlükte “hidayete erdirilmiş” demektir. Hz. Peygamber bu sıfatı ilk dört halife için de kullanmıştır: “Benim sünnetime ve benden sonraki hidayete erdirilmiş (mehdiyyîn), doğru yolda olan halifelerin sünnetine sarılın” (Ebû Dâvûd, Tirmizî). Bu kullanım, “mehdi” kavramının dilde bir sıfat olarak geniş bir anlam alanına sahip olduğunu ve sonradan tek bir kurtarıcı figürüne daraldığını gösterir.",
        tedebbur: [["Bir inancın tarih boyunca istismar edilmiş olması, onun dayandığı rivayetleri nasıl değerlendirmemiz gerektiğini etkiler mi?", "İstismarın inancın kendisini değil, ona dair iddiaları sorgulatması gerektiğini düşün."], ["Mehdi beklentisi insanı edilgenliğe mi, yoksa sorumluluğa mı yöneltmeli?", "Bugünkü sorumlulukları birinin gelmesine ertelemenin tehlikesini düşün."]] },
      10: { amac: "Ehl-i sünnet akidesini özlü bir klasik metinden okumak.", odak: "Nesefî akaidi bu yolda gördüğün meselelerden hangilerini nasıl ifade ediyor?",
        not: "Nesefî Akāid'i “Ehl-i hak, eşyanın hakikatlerinin sabit olduğunu ve onları bilmenin gerçek olduğunu söyler” cümlesiyle başlar. Bu, gerçekliği ve bilgiyi inkâr eden Sofistlere karşı ilk savunmadır: Akide konuşulmadan önce bilginin mümkün olduğu ortaya konur. Teftâzânî şerhinde Sofistleri üç gruba ayırır: gerçekliği tamamen inkâr edenler, her şeyin insanın inancına bağlı olduğunu söyleyenler ve hiçbir şeyi bilemeyeceğimizi söyleyenler.",
        tedebbur: [["Bir akide metninin bilginin imkânını savunarak başlaması bugün neden yeniden anlamlı?", "Hakikatin göreceli olduğunu söyleyen çağdaş görüşleri ve Teftâzânî'nin üç Sofist grubunu karşılaştır."], ["Nesefî'nin kısa ve kesin cümleleri ile Teftâzânî'nin uzun şerhleri arasındaki ilişki, klasik ilim geleneği hakkında ne söylüyor?", "Metnin ezberlenmesi ve şerhlerle derinleştirilmesi yöntemini düşün."]] },
      11: { amac: "Akıl, kalp ve iman ilişkisini büyük bir düşünürden okumak.", odak: "Gazâlî kelâmın sınırını nerede görür?",
        not: "Gazâlî, el-Munkız'da duyuların ve hatta aklın verdiği bilgiden bile şüphe ettiği bir dönemi anlatır. Bu şüpheden bir delille değil, “Allah'ın kalbe attığı bir nur” ile kurtulduğunu söyler. Ardından kelâm, felsefe, Bâtınîlik ve tasavvufu sırayla inceler ve aradığı kesinliği tasavvufun tecrübesinde bulduğunu ifade eder. Bu anlatı, bilginin yalnızca akıl yürütmeyle değil, kalbin arınmasıyla da elde edildiği düşüncesinin klasik metnidir.",
        tedebbur: [["Gazâlî'nin şüphesinden “kalbe atılan bir nur” ile kurtulması, imanın kaynağı hakkında ne söylüyor?", "Delilin imanı hazırladığını, ancak kesinliğin bir ilâhî lütuf olduğunu düşün."], ["Gazâlî'ye göre kelâm bir “ilaç” gibidir; herkese değil, ihtiyacı olana verilir. Bu benzetme sence doğru mu?", "Kelâmın şüpheleri gidermek için faydalı, ancak şüphesi olmayanda yeni şüpheler doğurabileceğini düşün."]] },
      12: { amac: "Kelâm geleneğine yöneltilen en güçlü eleştiriyi dinlemek.", odak: "İbn Teymiyye akıl ile nakil arasındaki ilişkiyi nasıl kurar?",
        not: "İbn Teymiyye, Der'ü teâruzi'l-akl ve'n-nakl'de, Fahreddin er-Râzî'nin “aklî kesinlik ile nakil çatışırsa nakil te'vîl edilir” şeklindeki “küllî kanun”una cevap verir. Ona göre bu kanunun kendisi tutarsızdır: Nakli akla dayandırıp sonra akılla nakli te'vîl etmek, nakli değersizleştirir. Sahih nakil ile sarih akıl hiçbir zaman çatışmaz; çatışma görünüyorsa ya nakil sahih değildir ya da akıl yürütme sağlam değildir.",
        tedebbur: [["Râzî ile İbn Teymiyye'nin tartışması, bugün bilim ile din ilişkisi tartışmalarına nasıl ışık tutar?", "“Çatışma varsa hangi taraf yanılıyor olabilir?” sorusunun iki yönlü sorulması gerektiğini düşün."], ["Bu yolda gördüğün Eş'arî, Mâtürîdî ve İbn Teymiyye çizgilerinden hangisi sana en ikna edici geldi? Neden?", "Cevabını, bu yolda gördüğün en az iki meseleye dayandırmaya çalış."]] }
    },
    sentez: "Kader veya haberî sıfatlar meselesini seç. Eş'arî, Mâtürîdî ve İbn Teymiyye çizgilerinin bu meseledeki görüşlerini üç kısa paragrafta özetle. Sonra en ikna edici bulduğun görüşü ve onu teşbihten veya cebirden nasıl koruduğunu açıkla." },

  cagdas: {
    buyukResim: "Bu yol, klasik fıkıh birikiminin bugünün sorularına nasıl cevap verdiğini göstermek için hazırlandı. Önce iki temel ilkeyi ediniyorsun: şeriatın amaçları (makâsıd) ve fetvanın şartlara göre değişmesi. Sonra bu ilkelerin hem klasik meselelerde hem de faiz, organ nakli, kripto, sigorta ve ötanazi gibi yeni meselelerde nasıl iş gördüğünü izliyorsun. En sonda üç çağdaş fakihin yöntemini karşılaştırıyorsun. Yolun ana sorusu şu: Nas değişmezken hüküm neden ve nasıl değişebilir?",
    hedefler: ["Makâsıd, örf, zaruret ve maslahat kavramlarının yeni meselelerde nasıl kullanıldığını anlayabilmek.", "Bir meselede hükmün illetinin değişip değişmediğini sorgulayabilmek.", "Kolaylaştırmak ile ruhsat avcılığı arasındaki ince sınırı görebilmek.", "Kurumsal fetva ile âlim ictihadını birbirinden ayırt edebilmek."],
    sure: "Yaklaşık 3 hafta", onbilgi: "“Fıkıh Nasıl Düşünür?” yolunu önce tamamlamak önerilir.",
    etaplar: [["İlkeler", 0, 1, "Makâsıd ile örf, fetvanın değişmesini nasıl farklı yönlerden açıklıyor? Biri amaca, diğeri vakıaya bakıyor; ikisi birlikte nasıl çalışır?"], ["Klasik meseleler, yeni sorular", 2, 7, "Bu altı meselede hükmün değişip değişmediği tartışmasının merkezinde hep aynı soru var: İllet nedir ve değişti mi? Her mesele için bu soruyu cevapla."], ["Makâsıd ve yeni varlıklar", 8, 11, "Kripto, sigorta ve ötanazi meselelerinde klasik kavramlar (mal, garar, tedavi) yeni bir gerçekliğe uygulanıyor. Hangisinde kavram en çok zorlanıyor?"], ["Çağdaş fakihler", 12, 14, "Zerkā, İbn Âbidîn ve Karadâvî'nin yöntemlerini yan yana koy. Gelenekle bağ ve yenilik cesareti bakımından nasıl farklılaşıyorlar?"]],
    adim: {
      0: { amac: "Şeriatın amaçlarını yeni meselelere yaklaşmanın anahtarı olarak edinmek.", odak: "Şeriat neyi korumayı amaçlar?",
        not: "Şâtıbî'ye göre makâsıdın kesinliği tek bir âyete veya hadise değil, şeriatın bütün hükümlerinin taranmasından (istikrâ) elde edilen bir sonuca dayanır. Tek tek her hüküm zannî olabilir, ama binlerce hükmün aynı amaca işaret etmesi kesin bir bilgi doğurur. Bu yüzden makâsıd, tek bir nassın zahirine karşı kullanılacak bir koz değil, nassların bütününün ortak yönünü gösteren bir pusuladır.",
        tedebbur: [["Makâsıdın “istikrâ” ile, yani tümevarımla bilinmesi, onu tek tek delillerin karşısına koymayı neden tehlikeli kılar?", "Bir pusulanın yönü göstermesi ile haritadaki yolları silmesi arasındaki farkı düşün."], ["Beş zarurî değeri kendi hayatındaki bir karara uygula. Hangi değerler çatışıyordu ve hangisini öne aldın?", "Can ile mal, din ile akıl gibi çatışmaları ve aralarındaki sıralamayı düşün."]] },
      1: { amac: "Fetvanın şartlara göre değişmesi ilkesini öğrenmek.", odak: "Bir fetva değişirse, şeriat da mı değişmiş olur?",
        not: "İbnü'l-Kayyim bu ilkeyi şöyle temellendirir: “Şeriat baştan sona adalet, rahmet, maslahat ve hikmettir. Adaletten zulme, rahmetten zıddına, maslahattan mefsedete, hikmetten abese çıkan her mesele, te'vîlle şeriata sokulmuş olsa bile şeriattan değildir” (İ'lâmü'l-muvakkıîn). Bu söz, fetvanın değişmesinin şeriattan uzaklaşmak değil, onun ruhuna sadık kalmak olduğunu savunur.",
        tedebbur: [["İbnü'l-Kayyim'in sözü bir ölçü olarak kullanılırsa, kim karar verecek: Bir fetvanın “adaletten zulme çıktığına” nasıl hükmedilir?", "Bu ölçünün keyfî kullanılma tehlikesini ve onu sınırlayan usul kurallarını düşün."], ["Nassın değişmesi ile nassın uygulandığı vakıanın değişmesi arasındaki farkı bir örnekle açıkla.", "Kefâetteki örfî unsurları veya mehrin miktarını düşün."]] },
      2: { amac: "Kesin bir haramın modern finans karşısında nasıl tartışıldığını görmek.", odak: "Kredi faizi Kur'an'ın yasakladığı ribâ mıdır?",
        not: "Bilâl, kalitesiz hurmadan iki ölçek verip karşılığında kaliteli hurmadan bir ölçek alınca Hz. Peygamber “Eyvah! Bu ribânın ta kendisidir. Böyle yapma; hurmanı başka bir şeyle sat, sonra onunla iyi hurmayı al” buyurmuştur (Buhârî, Müslim). Bu hadis, Hz. Peygamber'in bir yasağı bildirirken meşru bir çıkış yolu da gösterdiğini ortaya koyar. Ancak âlimler, bu tür çıkış yollarının (mehâric) gerçek ve bağımsız iki satış olması gerektiğini; görünüşte iki akit olup gerçekte faizli bir borca dönüşen düzenlemelerin (hile) ise bu ruhsatın kapsamına girmediğini vurgular.",
        tedebbur: [["Ribâ yasağının asıl gerekçesi sence nedir: sömürü mü, riskin tek tarafa yüklenmesi mi, paranın kendi kendine çoğalması mı?", "Her gerekçenin modern bankacılığa nasıl uygulanacağını ayrı ayrı düşün."], ["Âl-i İmrân 130'daki “kat kat” ifadesini bir sınırlama değil, bir tasvir olarak okumanın gerekçesi nedir?", "Bakara 279'un “anaparanız sizindir” ifadesini düşün."]] },
      3: { amac: "Nas olmayan bir meselede ictihadın nasıl yapıldığını görmek.", odak: "Bedenin saygınlığı ile başkasının hayatı çatışırsa hangisi öne alınır?",
        not: "Bu meselede Mecelle'de formüle edilen zaruret kaideleri belirleyicidir: “Zaruretler haramları mubah kılar” (md. 21), “Zaruret kendi ölçüsüyle takdir edilir” (md. 22) ve “Hâcet, genel veya özel olsun, zaruret yerine geçer” (md. 32). Organ naklinin caiz görülmesi birinci kaideye, organ ticaretinin yasaklanması ve bağışın şartlara bağlanması ise ikinci kaideye dayanır.",
        tedebbur: [["“Zaruret kendi ölçüsüyle takdir edilir” kaidesi, organ nakline izin verirken hangi sınırları koyar?", "Ticaretin, gereksiz alımın ve vericinin hayatını riske atmanın neden yasak kaldığını düşün."], ["İnsanın bedeni üzerindeki hakkı bir “mülkiyet” mi, bir “emanet” mi? Bu soru bağışın hükmünü nasıl etkiler?", "Malın da bir emanet olduğunu, buna rağmen sadaka verilebildiğini hatırla."]] },
      4: { amac: "Hükmün gerekçesi değiştiğinde ne olacağını tartışmak.", odak: "“Biri unutursa” gerekçesi kadının doğasına mı, o dönemin şartlarına mı bağlı?",
        not: "Usulde illet ile hikmet ayrılır. İllet, hükmün bağlandığı açık ve belirli vasıftır; hikmet ise hükmün amacıdır. Örneğin yolculukta namazı kısaltma hükmünün illeti yolculuk, hikmeti ise meşakkati gidermektir. Hükümler kural olarak değişken olan hikmete değil, belirli olan illete bağlanır. Kadının şahitliği meselesinde tartışma, “unutma ihtimali”nin bir illet mi yoksa bir hikmet mi olduğu, ve hangi vasfa bağlı olduğu konusunda düğümlenir.",
        tedebbur: [["İllet ile hikmet ayrımını kadının şahitliği meselesine uygula. “Biri unutursa” ifadesi hangisine daha yakın?", "Yolculuk ve meşakkat örneğiyle karşılaştır."], ["Bir hükmün gerekçesinin değiştiğini söylemek ile o hükmü değiştirmek arasında ne kadar mesafe var?", "Gerekçenin kesin bir illet mi, yoksa tahmin edilen bir hikmet mi olduğunun bu mesafeyi nasıl etkilediğini düşün."]] },
      5: { amac: "Bir azınlık görüşünün nasıl kanunlaştığını görmek.", odak: "Hz. Ömer'in uygulaması bir icmâ mı, bir siyaset tedbiri mi?",
        not: "Hz. Peygamber, üç talakla boşanan bir kadını eski kocasına “helal” kılmak için yapılan göstermelik evliliği (hülle) şiddetle kınamış; “Allah, hülle yapana ve kendisi için hülle yapılana lanet etsin” buyurmuştur (Tirmizî, İbn Mes'ûd'dan). Üç talakı tek sayan görüşü savunanların en güçlü pratik gerekçelerinden biri budur: Aceleyle verilmiş üç talakı geçerli saymak, pişman olan aileleri bu kınanmış yola itmektedir. Tartışma, bir hükmün sonuçlarının o hükmün yorumunu nasıl etkileyebileceğini gösterir.",
        tedebbur: [["Bir sahabe uygulamasını “icmâ” veya “siyaset tedbiri” olarak nitelemek, onun bağlayıcılığını nasıl değiştirir?", "İcmâın değişmez, siyaset tedbirinin ise şartlara bağlı olduğunu düşün."], ["Bir azınlık görüşünün devlet kanunuyla genel uygulamaya dönüşmesi, ictihadın mahiyeti açısından nasıl değerlendirilmeli?", "Mısır'ın 1929 kanununu ve Osmanlı'nın 1917 kararnamesini karşılaştır."]] },
      6: { amac: "Haramlığın illetini arayan bir tartışmayı izlemek.", odak: "Haram olan çalgının kendisi mi, birlikte bulunduğu ortam mı?",
        not: "Fıkıhtaki tartışmaya paralel olarak, İslâm medeniyetinde musiki bir ilim ve tedavi aracı olarak da işlenmiştir. Fârâbî'nin Kitâbü'l-Mûsîka'l-kebîr'i, musikinin teorisi üzerine yazılmış en kapsamlı eserlerden biridir. Osmanlı'da Edirne'deki II. Bayezid Darüşşifası gibi hastanelerde musikinin ruh hastalarının tedavisinde kullanıldığı nakledilir. Bu tarih, fakihlerin tartıştığı soruyu ortadan kaldırmaz; ama musikinin hükmünün, onun hangi amaçla ve hangi ortamda kullanıldığına bağlı olduğu görüşüne tarihî bir zemin sağlar.",
        tedebbur: [["Bir hadiste birkaç şeyin (içki, zina, ipek, çalgı) birlikte zikredilmesi, her birinin ayrı ayrı haram olduğunu mu, birlikte oluşturdukları ortamı mı gösterir?", "Sözün bağlamını ve “helal sayacaklar” ifadesinin vurgusunu düşün."], ["Gazâlî'nin hükmü dinleyenin hâline bağlaması, objektif bir fıkıh hükmü için yeterince belirli mi?", "Fıkhın dış ölçüler, tasavvufun iç hâller koyduğunu ve ikisinin nasıl birleştirilebileceğini düşün."]] },
      7: { amac: "Ruhsatların genişliği ve sınırını öğrenmek.", odak: "Bir ruhsatın şartları nastan mı, o dönemin örfünden mi çıkarıldı?",
        not: "Hz. Ali'den şu söz nakledilir: “Din re'y (akıl yürütme) ile olsaydı, mestin altını meshetmek üstünü meshetmekten daha uygun olurdu. Ben Resûlullah'ın mestlerinin üstünü meshettiğini gördüm” (Ebû Dâvûd). Bu söz, ruhsatların sınırlarının akla göre değil, nassa göre belirlendiğini gösterir. Çorap tartışmasında da asıl soru budur: Mezheplerin koyduğu şartlar, Ali'nin uyardığı türden bir akıl yürütmeye mi dayanıyor, yoksa nassın kendisinden mi çıkarılıyor?",
        tedebbur: [["Bir ruhsatın şartlarının nastan mı yoksa örften mi geldiğini nasıl ayırt edersin?", "Şartların doğrudan bir âyet veya hadiste geçip geçmediğine, yoksa o dönemin uygulamasından mı çıkarıldığına bak."], ["Ruhsatı genişletmek ile ibadeti hafife almak arasındaki sınır nerede?", "Ruhsatın amacının (zorluğu kaldırmak) gözetilip gözetilmediğini ölçü al."]] },
      8: { amac: "Makâsıdı bir kavram olarak sistemli bilmek.", odak: "Zarûriyyât, hâciyyât ve tahsîniyyât neyi ifade eder?",
        not: "İbn Âşûr, klasik beş zarurî değerin yanına şeriatın genel amaçları olarak fıtrat, semâha (kolaylık ve hoşgörü), eşitlik ve hürriyeti ekler. Ona göre bu kavramlar, şeriatın bütün hükümlerinde gözetilen temel niteliklerdir. Bu genişletme, makâsıdın yalnızca korunacak değerlerin bir listesi değil, şeriatın genel karakterini anlatan bir çerçeve olduğunu gösterir.",
        tedebbur: [["İbn Âşûr'un eklediği “hürriyet” ve “eşitlik” kavramları, klasik makâsıd listesini nasıl değiştirir?", "Klasik listenin “korunacak değerler”, İbn Âşûr'un ekleriniyse “şeriatın karakteri” olduğunu düşün."], ["Makâsıd düşüncesinin, tikel nassları devre dışı bırakacak şekilde kullanılması nasıl önlenebilir?", "Şâtıbî'nin makâsıdı nassların toplamından çıkardığını hatırla."]] },
      9: { amac: "Klasik kavramları yeni bir varlığa uygulamak.", odak: "Kripto bir mal mı, bir para mı, yoksa bir kumar mı?",
        not: "Gazâlî, İhyâ'nın şükür bölümünde paranın mahiyeti üzerine dikkat çekici bir açıklama yapar: Altın ve gümüş, kendileri için istenmeyen, diğer malların değerini ölçen “hâkimler” gibidir; değerleri, her şeyi yansıtan bir ayna gibi kendilerine ait bir renk taşımamalarından gelir. Parayı biriktirip dolaşımdan çekmek, bir hâkimi hapsetmek gibi bir zulümdür; ribâ ise parayı kendi amacının dışında, kendisinden kâr elde edilecek bir mala dönüştürmektir. Bu açıklama, kriptonun bir değer ölçüsü mü yoksa spekülasyon nesnesi mi olduğu sorusuna klasik bir ölçü sunar.",
        tedebbur: [["Mâlik'in deri para örneği, kripto paraların bir gün “para” sayılıp sayılamayacağı sorusuna nasıl ışık tutar?", "Paranın, maddesiyle değil toplumun kabulüyle para olduğunu düşün."], ["Yatırım ile kumar arasındaki sınırı nerede çizersin?", "Bir şeyin gerçek bir değer veya fayda üretip üretmediğini ve kazancın başkasının kaybına dayanıp dayanmadığını düşün."]] },
      10: { amac: "Akdin niteliğinin hükmü nasıl belirlediğini görmek.", odak: "Sigorta bir mübadele mi, bir dayanışma mı?",
        not: "İbn Teymiyye, garar yasağının gerekçesini şöyle açıklar: Garar, akıbeti belirsiz olan şeydir; yasaklanmasının sebebi, kumar gibi, taraflardan birinin diğerinin aleyhine haksız kazanç elde etmesine ve aralarında düşmanlık doğmasına yol açmasıdır. Bu yaklaşıma göre bir akdi değerlendirirken sorulacak ilk soru, belirsizliğin miktarı değil, bu belirsizliğin bir tarafı haksız yere zenginleştirip zenginleştirmediğidir. Sigorta tartışması bu soruya verilecek cevapla doğrudan ilişkilidir.",
        tedebbur: [["Bir akdin ivaz mı yoksa teberru mu olduğuna nasıl karar verirsin: tarafların niyetine mi, yoksa akdin ekonomik sonucuna mı bakarak?", "Tekâfül ile ticari sigortanın ekonomik sonuçlarının benzerliğini, ama yapılarının farklılığını düşün."], ["Zerkā'nın âkıle kıyası ikna edici mi?", "Kıyasın akdin “şekline” mi, yoksa “işlevine” mi dayandığını sorgula."]] },
      11: { amac: "Fiil ile terk arasındaki ahlâkî ayrımı tartışmak.", odak: "Öldürmek ile ölmeye bırakmak arasında fark var mı?",
        not: "Klasik fıkıh, ölüme yaklaşmış insanı korumak için “ölüm hastalığı” (maraz-ı mevt) adıyla özel bir hukuk geliştirmiştir. Ölüm hastalığındaki kişi, mirasçılarının hakkını korumak için malının ancak üçte birini bağışlayabilir; bu dönemde mirastan mahrum etmek amacıyla eşini boşarsa, eşi yine de mirasçı olur. Bu hükümler, fıkhın hayatın son dönemini ihmal etmediğini, aksine o dönemi hem hastanın hem de yakınlarının haklarını koruyan bir düzenle çevrelediğini gösterir.",
        tedebbur: [["Hayatın bir “emanet” olarak görülmesi ile bir “özerklik hakkı” olarak görülmesi arasındaki fark, acı çeken bir hastaya bakışını nasıl değiştirir?", "Emanet anlayışının acıyı küçümsemediğini, aksine bakımı ve teselliyi bir görev hâline getirdiğini düşün."], ["“Öldürmek” ile “ölmeye bırakmak” arasındaki ayrımın sınırları nerede bulanıklaşır?", "Beslenmenin kesilmesi ile faydasız bir tedavinin kesilmesini karşılaştır."]] },
      12: { amac: "Klasik fıkıhtan genel teoriler çıkarmayı bir modelden öğrenmek.", odak: "Klasik fıkıh modern hukuk sistematiğiyle nasıl sunulabilir?",
        not: "Zerkā, dünyanın ilk büyük fıkıh ansiklopedisi projelerinden birine de öncülük etmiştir. 1950'lerde Şam'da başlayan ve sonra Kuveyt'te el-Mevsûatü'l-fıkhiyye adıyla tamamlanan bu ansiklopedi, mezheplerin görüşlerini alfabetik maddeler hâlinde bir araya getirir. Bu proje, fıkhı modern bir araştırmacının kolayca ulaşabileceği bir başvuru kaynağına dönüştürme çabasıdır. Zerkā'nın genel teoriler yaklaşımı ile ansiklopedi projesi, aynı amacın iki yüzüdür: Klasik birikimi kaybetmeden yeni bir düzenle sunmak.",
        tedebbur: [["Fıkhı “genel teoriler” hâlinde sunmanın avantajı ve riski nedir?", "Dağınık hükümleri birleştirmenin faydasını ve yabancı bir kategoriyi dayatmanın tehlikesini düşün."], ["Zerkā'nın sigortayı caiz görmesi, “akitlerde aslolan ibâhadır” ilkesine nasıl dayanıyor?", "Yeni bir akdin, yasaklanmış bir akde benzemiyorsa mubah sayılabileceğini düşün."]] },
      13: { amac: "Örfün fetvadaki yerini bir son dönem fakihinden görmek.", odak: "Kitaplardaki ifade ile insanların bugünkü örfü çatışırsa müftü ne yapmalı?",
        not: "İbn Âbidîn örfü savunduğu kadar, örfün her zaman meşru olmadığını da gösterir. Şifâü'l-alîl adlı risalesinde, vefat edenler için ücret karşılığında hatim okutmanın ve bunun vasiyet edilmesinin caiz olmadığını savunur; bu uygulama yaygın bir örf hâline gelmiş olsa bile. Bu, fıkıhta “sahih örf” ile “fâsid örf” arasındaki ayrımın canlı bir örneğidir: Örf, ancak bir nassa aykırı olmadığı ve bir haramı helal kılmadığı sürece hükme esas olabilir.",
        tedebbur: [["Örf değişince hükmü değiştirmek neden mezhepten bir çıkış değil, mezhebe sadakattir?", "İmamların kendi zamanlarının örfünü dikkate alarak hüküm verdiklerini, bugün de aynı şeyi yapmanın onların yöntemine uymak olduğunu düşün."], ["Hangi hükümler örfe bağlıdır, hangileri değildir? Bu ayrımı nasıl yaparsın?", "Hükmün doğrudan bir nassa mı, yoksa toplumun bir uygulamasına mı dayandığına bak."]] },
      14: { amac: "Çağdaş bir fakihin yöntemini ve eleştirilerini birlikte değerlendirmek.", odak: "Kolaylaştırmak ne zaman ruhsat avcılığına dönüşür?",
        not: "Karadâvî'nin geliştirdiği “azınlık fıkhı”, Batı'da yaşayan Müslümanların kendine özgü şartlarını gözeten bir fıkıh anlayışıdır. Avrupa Fetva ve Araştırma Konseyi'nin, başka imkânı olmayan Müslümanların ihtiyaç hâlinde ev kredisi kullanabileceğine dair 1999 fetvası bu anlayışın en tartışmalı uygulamalarından biridir. Eleştirmenler, bu yaklaşımın zaruret kavramını aşırı genişlettiğini ve ribâ yasağını aşındırdığını ileri sürer.",
        tedebbur: [["Kolaylaştırmanın (teysîr) meşru sınırını nasıl belirlersin?", "Zorluğun gerçek mi yoksa varsayılan mı olduğunu ve zaruret ile hâcet arasındaki farkı düşün."], ["Bu yolda gördüğün meselelerden birinde sen fetva verecek olsaydın hangi ilkeyi belirleyici sayardın?", "Makâsıd, örf, zaruret ve illet ilkelerinden birini seçip gerekçelendir."]] }
    },
    sentez: "Bu yolda incelediğin çağdaş meselelerden birini seç (faiz, organ nakli, kripto, sigorta veya ötanazi). Meseleyi şu dört soruyla analiz et: Hangi klasik kavrama bağlanıyor? Hükmün illeti ne? Bu illet bugün değişti mi? Hangi makâsıd değeri belirleyici? Sonunda kendi değerlendirmeni yaz." },

  "kuran-konulari": {
    buyukResim: "Bu yol, Kur'an'ı sure sure değil, kavram kavram okumak için hazırlandı. Her konuda Kur'an'ın farklı surelerde aynı kavrama nasıl döndüğünü, onu nasıl derinleştirdiğini ve bir kıssayla nasıl somutlaştırdığını göreceksin. Yolun sırası bilinçli olarak seçildi: Önce insanın iç dünyası (kalp, ilim, takva, rahmet, tevbe), sonra hayatın karşısındaki tavrı (şükür, sabır, tevekkül, rızık), sonra toplumdaki sorumluluğu (adalet, emanet, imtihan, dua, anne-baba) ve en sonda hepsinin anlamını veren âhiret. Her konuda kendine bir soru sor: Bu kavram benim hayatımda nerede?",
    hedefler: ["Kur'an'ın ana kavramlarını âyetler, kıssalar ve hadislerle birlikte kavrayabilmek.", "Kavramlar arasındaki bağları (sabır-şükür, tevbe-rahmet, takva-kalp) görebilmek.", "Kur'an'ı tedebbür ederek okumanın bir yöntemini edinebilmek.", "Her kavramın gündelik hayattaki karşılığını bulabilmek."],
    sure: "15 gün; her gün bir konu", onbilgi: "Gerekmez.",
    etaplar: [["İç dünya", 0, 4, "Kalp, ilim, takva, rahmet ve tevbe arasında bir zincir kur: Hangisi hangisine yol açıyor?"], ["Hayatın karşısında", 5, 8, "Şükür ve sabır, müminin iki kanadı olarak anılır. Tevekkül ve rızık anlayışı bu iki kanadı nasıl destekler?"], ["Toplum ve sorumluluk", 9, 13, "Adalet ve emanet toplumsal, imtihan ve dua bireysel, anne-baba hakkı ise ailevî bir sorumluluk. Bu beş kavramı birleştiren ortak bir ilke var mı?"], ["Son", 14, 14, "Âhiret inancı, bu yolda gördüğün diğer on dört kavramın her birine ne anlam katıyor?"]],
    adim: {
      0: { amac: "Kur'an'da kalbin anlama ve yönelme merkezi olduğunu kavramak.", odak: "Kur'an neden “akletmeyi” kalbe nispet eder?",
        not: "Kur'an insanın iç dünyası için tek bir kelime kullanmaz: sadr (göğüs), kalb, fuâd ve lübb. Hakîm et-Tirmizî, Beyânü'l-fark adlı eserinde bunları iç içe dört katman olarak açıklar: Sadr, İslâm'ın; kalb, imanın; fuâd, marifetin; lübb ise tevhidin yeridir. Her katman bir öncekinin içindedir, tıpkı bir meyvenin kabuğu, eti ve çekirdeği gibi. Bu sınıflandırma, Kur'an'ın bu kelimeleri hangi bağlamlarda kullandığına dikkatle bakmaya davet eder: “Göğsünü açmadık mı” (İnşirâh 1), “Kalbin gördüğünü fuâd yalanlamadı” (Necm 11), “Ancak lübb sahipleri öğüt alır” (Bakara 269).",
        tedebbur: [["Kalbin “dönen” bir şey olması, imanın korunması hakkında ne söylüyor?", "İmanın bir kez kazanılıp bırakılacak bir şey değil, sürekli bakım isteyen bir hâl olduğunu düşün."], ["Hac 46'da gözlerin değil kalplerin kör olduğu söyleniyor. Kalp körlüğünün belirtileri nelerdir?", "Hakikati gördüğü hâlde kabul etmemeyi, uyarıları duyduğu hâlde etkilenmemeyi düşün."]] },
      1: { amac: "İlmin haşyet ve sorumlulukla bağını görmek.", odak: "Kur'an'a göre ilim insana ne kazandırmalı?",
        not: "Buhârî, Sahîh'inin ilim bölümünde bir babı “İlim, söz ve amelden öncedir” diye adlandırır ve buna delil olarak şu âyeti gösterir: “Bil ki Allah'tan başka ilah yoktur; günahın için bağışlanma dile” (Muhammed 19). Âyette önce bilmek, sonra amel (istiğfar) emredilir. Buhârî'nin bu tercihi, ilmin amele yön veren bir pusula olduğunu, ama amelden kopuk bir bilginin de eksik kaldığını gösterir.",
        tedebbur: [["Tefekkür, tezekkür ve tedebbür arasındaki farkı kendi Kur'an okumanda nasıl gözlemleyebilirsin?", "Bir âyet okurken kâinatı düşünmeyi, bildiğini hatırlamayı ve âyetin senin için sonucunu sormayı ayırt et."], ["Muhammed 24'te tedebbür etmemek neden “kalpteki kilitler”le ilişkilendiriliyor?", "Anlamın, akıldan önce kalbin açıklığına bağlı olduğunu düşün."]] },
      2: { amac: "Takvanın derecelerini ve kalple ilişkisini öğrenmek.", odak: "“Hakkıyla takva” ile “gücünüz yettiğince takva” nasıl bağdaşır?",
        not: "Takva kelimesi “korunmak, kendini sakınmak” anlamındaki vikāye kökünden gelir. İbn Recep el-Hanbelî, takvayı “kulun, Allah'ın gazabı ve azabı ile kendisi arasına bir kalkan koyması” olarak tanımlar; bu kalkan da emirleri yerine getirmek ve yasaklardan kaçınmaktır. Bu kök anlam, takvanın bir korku hâli olmaktan önce bir korunma tedbiri olduğunu gösterir: İnsan sevdiği bir şeyi kaybetmemek için nasıl özen gösteriyorsa, takva da Allah ile ilişkisini kaybetmemek için gösterilen özendir.",
        tedebbur: [["Takvanın bir “bilgi kaynağı” olması ne demektir? Günahın düşünceyi bulandırdığı bir an yaşadın mı?", "Kalbi meşgul eden bir şeyin, doğru karar vermeyi nasıl zorlaştırdığını düşün."], ["“Gücünüz yettiğince” kaydı takvayı gevşetiyor mu, yoksa onu gerçekçi mi kılıyor?", "Allah'ın insana gücünden fazlasını yüklemediğini, ama gücünün tamamını istediğini düşün."]] },
      3: { amac: "Rahmetin ilâhî bir ilke olduğunu ve insan merhametinin kaynağını görmek.", odak: "Rahmân ile Rahîm arasında fark var mı?",
        not: "Tâif'te taşlanıp kanlar içinde kalan Hz. Peygamber'e dağlar meleği gelmiş ve “Dilersen şu iki dağı onların üzerine kapatayım” demişti. Hz. Peygamber şöyle cevap verdi: “Hayır, umarım Allah onların soyundan, yalnız O'na ibadet eden ve O'na hiçbir şeyi ortak koşmayan kimseler çıkarır” (Buhârî, Müslim). Bu olay, rahmetin yalnızca sevenlere değil, incitenlere karşı da gösterilebildiğini ve rahmetin gözünün bugüne değil, geleceğe baktığını gösterir.",
        tedebbur: [["Rahmetin liderliğin temeli olması, senin aile veya iş hayatındaki sorumluluklarına nasıl uygulanabilir?", "Sertliğin insanları nasıl uzaklaştırdığını ve yumuşaklığın nasıl birleştirdiğini düşün."], ["Allah'ın rahmetinin gazabını geçmesi, Allah'a bakışını ve kendi günahlarına bakışını nasıl etkiliyor?", "Ümitsizliğin de bir tür yanlış Allah tasavvuru olduğunu düşün."]] },
      4: { amac: "Tevbenin şartlarını ve ümit kapısını öğrenmek.", odak: "Hangi günahlar tevbe ile affedilir?",
        not: "Gazâlî, İhyâ'nın tevbe bölümünde tevbeyi üç halkalı bir zincir olarak açıklar: ilim, hâl ve amel. Önce günahın ne kadar zararlı olduğunu ve insanı Allah'tan nasıl uzaklaştırdığını bilmek (ilim) gerekir. Bu bilgi kalpte bir yanma ve pişmanlık (hâl) doğurur. Bu pişmanlık da günahı bırakmaya ve bir daha yapmamaya kararlı olmaya (amel) yöneltir. Gazâlî'ye göre ilim olmadan pişmanlık, pişmanlık olmadan da gerçek bir değişim olmaz.",
        tedebbur: [["Tevbenin bir “zaman” meselesi olması, onu ertelemek hakkında ne söylüyor?", "Ertelenen tevbenin bir kumar olduğunu, çünkü ölümün vaktinin bilinmediğini düşün."], ["Allah'ın kulunun tevbesine sevinmesi hadisi, tevbeyi bir korku eylemi olmaktan çıkarıp neye dönüştürüyor?", "Kaybolan bir yolcunun devesini bulduğundaki sevinci düşün."]] },
      5: { amac: "Şükrün bir amel olduğunu kavramak.", odak: "Şükür sadece dille mi yapılır?",
        not: "İbnü'l-Kayyim, Medâricü's-sâlikîn'de şükrün beş temel üzerine kurulduğunu söyler: Şükredenin, şükredilene boyun eğmesi; onu sevmesi; nimetini itiraf etmesi; onunla O'nu övmesi; ve o nimeti O'nun hoşlanmadığı bir yerde kullanmaması. Bu tanım, şükrü bir “teşekkür sözü” olmaktan çıkarıp bir ilişki biçimine dönüştürür: Şükür, nimeti verenle kurulan saygı ve sevgi ilişkisinin adıdır.",
        tedebbur: [["Bir nimeti “imtihan” olarak görmek, ona sahip olma şeklini nasıl değiştirir?", "Nimeti bir hak olarak görmek ile bir emanet olarak görmek arasındaki farkı düşün."], ["Cüneyd'in tanımına göre, sahip olduğun bir nimeti şu an nasıl kullanıyorsun?", "Sağlık, vakit veya bir yetenek gibi bir nimeti seç ve onu nerede kullandığını düşün."]] },
      6: { amac: "Sabrın üç alanını ve aktif bir direnç olduğunu görmek.", odak: "Sabrın en zor alanı hangisidir?",
        not: "Klasik âlimler arasında “Şükreden zengin mi, yoksa sabreden fakir mi daha üstündür?” sorusu uzun uzun tartışılmıştır. İbnü'l-Kayyim, Uddetü's-sâbirîn'de bu tartışmayı ayrıntılı olarak ele alır ve hocası İbn Teymiyye'nin görüşünü benimser: Hangisinin takvası daha fazlaysa o daha üstündür. Zenginlik ve fakirlik, her biri kendi ödevini getiren iki ayrı imtihandır; üstünlük durumun kendisinde değil, o durumda nasıl yaşandığındadır.",
        tedebbur: [["Allah'a şikâyet etmek neden sabra aykırı değildir?", "Şikâyetin muhatabının, şikâyetin anlamını nasıl değiştirdiğini düşün."], ["Sabrın “aktif bir direnç” olması ne demektir? Sabrı edilgen bir bekleyişten ayıran nedir?", "Âl-i İmrân 200'deki “sabredin, sabırda yarışın, nöbette kalın” emrini düşün."]] },
      7: { amac: "Tevekkülün sebeplere sarılmakla birlikte olduğunu öğrenmek.", odak: "Tevekkül ile tembellik (tevâkül) arasındaki fark nedir?",
        not: "Hz. Ömer, veba bulunan Şam'a girmekten vazgeçince Ebû Ubeyde ona “Allah'ın kaderinden mi kaçıyorsun?” diye sordu. Ömer şöyle cevap verdi: “Evet, Allah'ın kaderinden yine Allah'ın kaderine kaçıyoruz. Bir vadin olsa, biri verimli diğeri çorak iki yamacı bulunsa, verimli yamaçta otlatırsan Allah'ın kaderiyle, çorak yamaçta otlatırsan yine Allah'ın kaderiyle otlatmış olmaz mısın?” (Buhârî, Müslim). Sebeplere sarılmak kaderin dışına çıkmak değil, kaderin içinde doğru seçimi yapmaktır.",
        tedebbur: [["Ömer'in iki yamaç benzetmesi, tevekkül ile sebeplere sarılma arasındaki ilişkiyi nasıl açıklıyor?", "Her iki seçimin de kader dahilinde olduğunu, ama birinin akla ve sorumluluğa uygun olduğunu düşün."], ["Kaygılandığın bir işte senin elindeki ile elinde olmayanı ayırabiliyor musun?", "Elindeki sebepleri yerine getirip sonucu Allah'a bırakmanın huzurunu düşün."]] },
      8: { amac: "Rızkın kaynağını ve imtihan boyutunu kavramak.", odak: "Rızkın bolluğu sevginin, darlığı gazabın işareti midir?",
        not: "Hz. Ömer'in rivayet ettiğine göre Hz. Peygamber şöyle buyurmuştur: “Eğer Allah'a hakkıyla tevekkül etseydiniz, kuşları rızıklandırdığı gibi sizi de rızıklandırırdı: Sabah aç çıkarlar, akşam tok dönerler” (Tirmizî, İbn Mâce). Âlimler bu hadisteki inceliğe dikkat çeker: Kuşlar yuvalarında oturup beklemez; sabah çıkar ve rızkın peşine düşerler. Tevekkül, sebeplere sarılmayı bırakmak değil, sebeplere sarılırken kalbin güvenini Allah'a bağlamaktır.",
        tedebbur: [["“Rızık Allah'tandır, yolu ise kulun seçimidir” anlayışı, kazanç yoluna dair sorumluluğu nasıl artırır?", "Rızkın garanti edilmiş olmasının, haram yola sapmak için hiçbir gerekçe bırakmadığını düşün."], ["Kārûn'un “Bu bana bilgim sayesinde verildi” sözü, bugün başarıyı nasıl yorumladığımıza dair ne söylüyor?", "Başarıyı tamamen kendine nispet etmenin kibir ve nankörlüğe nasıl yol açtığını düşün."]] },
      9: { amac: "Adaletin peygamberlerin gönderiliş amacı olduğunu görmek.", odak: "Düşmana karşı adalet neden takvaya daha yakındır?",
        not: "Nisâ 105-113. âyetlerin iniş sebebi olarak şu olay nakledilir: Medine'de Tu'me b. Übeyrik adlı bir Müslüman bir zırh çalmış, suçu bir Yahudinin üzerine atmıştı. Yakınları da Hz. Peygamber'in yanında onu savunmuştu. İnen âyetler, Yahudiyi aklayıp asıl suçluyu ortaya çıkardı ve Peygamber'e “hainlerin savunucusu olma” uyarısında bulundu (Tirmizî, Taberî). Kur'an'ın bir Yahudiyi bir Müslümana karşı savunması, adaletin kimlik üstü bir ilke olduğunun en çarpıcı örneklerinden biridir.",
        tedebbur: [["Adaletin dinî kimlikten önce gelmesi ne demektir? Bu fikir hangi tehlikeleri önler?", "Bir topluluğun kendi mensuplarının zulmünü görmezden gelmesinin sonuçlarını düşün."], ["Mâide 8'deki “bir topluluğa olan öfkeniz sizi adaletsizliğe sürüklemesin” uyarısını kendi hayatından bir örnekle düşün.", "Sevmediğin birinin haklı olduğu bir durumu hatırla."]] },
      10: { amac: "İnsanın yüklendiği emanetin anlamını ve liyakat ilkesini öğrenmek.", odak: "Emanet neyi kapsar?",
        not: "İbn Teymiyye, es-Siyâsetü'ş-şer'iyye adlı eserini iki âyet üzerine kurar: “Allah size emanetleri ehline vermenizi ve insanlar arasında hükmettiğinizde adaletle hükmetmenizi emreder” (Nisâ 58) ve ardından gelen yöneticilere itaat âyeti (Nisâ 59). Ona göre devlet yönetiminin özü, görevleri ehline vermek (liyakat) ve adaletle hükmetmektir. Bir göreve ehil olanı bırakıp akrabayı veya yakını atamak, emanete ihanettir.",
        tedebbur: [["Liyakat ilkesinin bir “emanet” meselesi olarak görülmesi, onu sadece bir verimlilik ilkesi olmaktan çıkarıp neye dönüştürüyor?", "Liyakatsizliğin bir dinî sorumluluk ve ihanet olarak görülmesinin anlamını düşün."], ["Senin hayatında “ehline vermen” gereken emanetler neler?", "Bir görev, bir sır veya bir karar yetkisini düşün."]] },
      11: { amac: "Hayatı bir imtihan olarak okumayı öğrenmek.", odak: "Nimet de bir imtihan olabilir mi?",
        not: "Mülk 2'de ölüm ve hayatın, “hanginizin daha güzel amel yapacağını” sınamak için yaratıldığı bildirilir. Fudayl b. İyâz bu âyetteki “daha güzel amel”i “en ihlaslı ve en doğru olan” diye açıklar: “Amel ihlaslı olur da doğru olmazsa kabul edilmez; doğru olur da ihlaslı olmazsa yine kabul edilmez. İhlaslı olan, Allah için yapılandır; doğru olan da sünnete uygun olandır.” Dikkat edilirse âyet “daha çok amel” değil, “daha güzel amel” der: İmtihanın ölçüsü nicelik değil, niteliktir.",
        tedebbur: [["Hızır kıssası, anlayamadığın bir acı karşısında nasıl bir tavır önerir?", "Mûsâ'nın sabredemeyişini ve sonunda hikmeti öğrenişini düşün."], ["Hayatındaki en büyük nimetle nasıl bir imtihandan geçiyorsun?", "Nimetin seni Allah'a mı yaklaştırdığını, yoksa O'ndan mı uzaklaştırdığını düşün."]] },
      12: { amac: "Duanın kulluğun özü olduğunu kavramak.", odak: "Her şey takdir edilmişse dua neyi değiştirir?",
        not: "Kur'an'daki duaların büyük çoğunluğu “Rabbenâ” veya “Rabbi” (Rabbimiz, Rabbim) hitabıyla başlar. Âdem ile Havvâ'nın tevbesi (A'râf 23), İbrâhim'in duaları ve Bakara suresinin sonundaki dua bunun örnekleridir. “Rab” ismi, terbiye eden, yetiştiren ve ihtiyaçları gözeten anlamına gelir. Dua eden kul, böylece Allah'a, kendisini yaratıp büyüten ve her ihtiyacını bilen Rabbi olarak yönelir. Bu hitap, duanın bir talep listesinden önce bir yakınlık ve aidiyet ifadesi olduğunu gösterir.",
        tedebbur: [["Gazâlî'nin açıklaması, duanın kaderle ilişkisini nasıl bir çelişki olmaktan çıkarıyor?", "Hem hastalığın hem de ilacın takdir edilmiş olmasını düşün."], ["Duaların daha çok bir ihtiyaç listesi mi, yoksa bir yakınlık arayışı mı?", "Furkān 77'deki “Duanız olmasa Rabbim size ne diye değer versin” âyetini düşün."]] },
      13: { amac: "Anne baba hakkının yerini ve sınırını öğrenmek.", odak: "Anne babaya itaatin sınırı nedir?",
        not: "Hz. Peygamber, Hz. Ömer'e Yemen'den Üveys el-Karanî adında birinin geleceğini, onun annesine çok iyilik eden biri olduğunu ve ondan kendisi için bağışlanma dilemesini istemesini söylemişti (Müslim). Üveys, annesine bakmak için Hz. Peygamber'i ziyaret edememiş, ama bu iyiliği sebebiyle övgüye mazhar olmuştur. Bu kıssa, anne babaya hizmetin, en büyük manevi fırsatlardan birini bile öne geçebilecek bir ibadet olduğunu gösterir.",
        tedebbur: [["İtaat ile saygı arasındaki fark nedir? Hz. İbrâhim kıssası bu farkı nasıl gösteriyor?", "İbrâhim'in babasının inancına uymamasını, ama ona karşı edebini korumasını düşün."], ["Anne baban vefat etmişse veya hayattaysa, onlara bu hafta yapabileceğin somut bir iyilik ne?", "Bir dua, bir ziyaret, bir dostlarını arama veya bir sadaka düşün."]] },
      14: { amac: "Bütün temaları âhiret bilinciyle birleştirmek.", odak: "Kur'an âhireti hangi aklî delillerle temellendirir?",
        not: "Hz. Peygamber, Abdullah b. Ömer'in omzundan tutarak “Dünyada bir garip veya bir yolcu gibi ol” buyurmuştur. İbn Ömer de şöyle derdi: “Akşama erişince sabahı bekleme, sabaha erişince akşamı bekleme. Sağlığından hastalığın için, hayatından ölümün için pay al” (Buhârî). Garip, yaşadığı yere ait olmadığını bilir; yolcu ise bir menzilden geçtiğini. Âhiret inancı, dünyayı reddetmeyi değil, ona bir yolcunun gözüyle bakmayı öğretir.",
        tedebbur: [["Allah'ın isimlerinden hareketle âhireti düşünmek, âhiret inancını nasıl bir akıl yürütme hâline getirir?", "Hakîm, Rahîm ve Adl isimlerinin her birinin âhireti nasıl gerektirdiğini düşün."], ["Âhiret bilinci, bu yolda gördüğün diğer kavramlara (sabır, şükür, adalet, emanet) nasıl bir anlam katıyor?", "Âhiret olmasaydı sabrın, adaletin veya emanetin anlamının nasıl değişeceğini düşün."]] }
    },
    sentez: "On beş konudan birbirine bağlı üçünü seç (örneğin sabır, şükür ve imtihan). Her biri için bir âyet ve bir kıssa yaz, sonra bu üç kavramın birbirini nasıl tamamladığını kendi hayatından bir örnekle anlat." },

  aile: {
    buyukResim: "Bu yol, aile hukukunu bir kurallar listesi olarak değil, mezheplerin aileyi ve kadının, erkeğin ve çocuğun haklarını nasıl düşündüğünü anlamak için hazırlandı. Önce nikâhın kuruluşunu (şartlar, velî, denklik), sonra evlilikteki hakları ve örfün rolünü, en sonda da ayrılık, şahitlik ve mezhepler arası tercih meselelerini görüyorsun. Yol boyunca bir soruyu aklında tut: Bu hükümlerin amacı kimi, neye karşı korumak?",
    hedefler: ["Nikâhın şartlarındaki mezhep farklarının arkasındaki farklı aile anlayışlarını görebilmek.", "Nafaka ve kefâet meselelerinde ihtilafın kökenini anlayabilmek.", "Örfün aile hukukundaki rolünü ve sınırını değerlendirebilmek.", "Mezhepler arası tercihin meşruiyetini ve sınırlarını tartışabilmek."],
    sure: "Yaklaşık 2 hafta", onbilgi: "“Fıkıh Nasıl Düşünür?” yolunu önce tamamlamak faydalıdır.",
    etaplar: [["Nikâh", 0, 2, "Velî ve kefâet, nikâhta kimin iradesinin ne ölçüde belirleyici olduğu sorusuna farklı cevaplar veriyor. Hanefîler ile cumhurun bu konudaki temel farkını tek cümleyle ifade et."], ["Haklar ve örf", 3, 4, "Nafakanın miktarı ve kefâetin unsurları neden örfe bırakılmış? Örfün hüküm üzerindeki gücü nerede sınırlanmalı?"], ["Ayrılık, şahitlik ve tercih", 5, 8, "Üç talak, kadının şahitliği ve telfîk meselelerinde ortak bir soru var: Azınlıkta kalan bir görüş ne zaman ve nasıl genel uygulamaya dönüşebilir?"]],
    adim: {
      0: { amac: "Evliliğin pratik çerçevesini ve nikâhın şartlarını edinmek.", odak: "Nikâhın geçerli olması için mezheplere göre neler gerekir?",
        not: "Rûm 21'de evlilik üç kavramla tanımlanır: sükûn (huzur), meveddet (sevgi) ve rahmet (merhamet). Müfessirler bu üçlünün bir sıralama taşıdığını söyler: Evlilik önce bir huzur ve sığınak sağlar; sevgi, özellikle gençlik yıllarında güçlüdür; rahmet ise sevginin azaldığı, yaşlılık ve hastalık gibi zor zamanlarda bile ilişkiyi ayakta tutar. Fıkhın hükümleri, bu üç değeri korumaya yönelik bir çerçevedir.",
        tedebbur: [["Sevgi ile merhamet arasındaki fark nedir? Bir evlilikte hangisi daha kalıcıdır?", "Duygunun değişkenliğini ve merhametin bir irade ve sorumluluk olduğunu düşün."], ["Nikâhın şartlarındaki mezhep farkları, Rûm 21'deki üç değeri korumaya nasıl hizmet ediyor?", "Şahit ve ilan şartlarının evliliği gizlilikten ve kötüye kullanımdan nasıl koruduğunu düşün."]] },
      1: { amac: "Kadının iradesi ile velînin koruması arasındaki dengeyi anlamak.", odak: "Ergin bir kadın kendi nikâhını kıyabilir mi?",
        not: "Mâlikî mezhebinde ilginç bir ayrım vardır: İmam Mâlik'ten nakledilen bir görüşe göre, toplumda tanınan ve ailesiyle anılan bir kadın ile böyle bir aile çevresi olmayan bir kadın aynı değildir. İkincisi, yakın bir velîsi yoksa, bulunduğu yerdeki güvenilir bir Müslümanı velî tayin ederek evlenebilir (velâyet-i âmme). Bu ayrım, velî şartının amacının kadını kısıtlamak değil, onu ve ailesini korumak olduğunu; bu amacın bulunmadığı yerde şartın da hafiflediğini gösterir.",
        tedebbur: [["Bir ravinin kendi rivayetini hatırlamaması, o rivayetin güvenilirliğini etkiler mi? İki tarafın gerekçelerini değerlendir.", "Hafızanın doğal zaaflarını ve güvenilir bir talebenin nakil değerini karşılaştır."], ["Hanefîler kadının iradesini, cumhur ise velînin korumasını öne çıkarıyor. İki yaklaşım da kadını korumayı amaçlıyorsa, bu amaç nasıl farklı yollarla gerçekleşiyor?", "Bir yetişkinin kendi kararını verme hakkı ile tecrübeli birinin rehberliğinin faydasını karşılaştır."]] },
      2: { amac: "Örfün hukukî bir hakka nasıl dönüştüğünü görmek.", odak: "Kefâet ahlâkî bir üstünlük iddiası mı, yoksa bir hak mı?",
        not: "Hz. Peygamber, Kureyşli Zeyneb bint Cahş'ı âzatlı Zeyd b. Hârise ile evlendirmiştir. Ahzâb 36'daki “Allah ve Resûlü bir işe hüküm verdiğinde mümin bir erkek ve kadın için o işte seçim hakkı yoktur” âyeti, Zeyneb ve ailesinin bu evliliğe başta isteksiz olması üzerine inmiştir. Bu evlilik, soy farkının dinî bir engel olmadığını gösterir. Ancak kefâeti savunanlar, burada rızanın sonunda gerçekleştiğini ve kefâetin rızayla düşen bir hak olduğunu hatırlatır.",
        tedebbur: [["Zeyneb ile Zeyd'in evliliği, kefâetin varlığını mı yoksa rızayla düşebilirliğini mi gösterir?", "Bir hakkın var olması ile o haktan vazgeçilebilmesi arasındaki farkı düşün."], ["Bugün eş seçiminde dikkate alınması gereken “denklik” unsurları sence nelerdir?", "Eğitim, değerler, dindarlık ve hayat beklentisi gibi unsurları klasik unsurlarla karşılaştır."]] },
      3: { amac: "Bir nitelik farkının zincirleme sonuçlarını izlemek.", odak: "Nafaka bir karşılık mı, bir bağlılık hakkı mı?",
        not: "Hind bint Utbe hadisi (“Sana ve çocuğuna örfe göre yetecek kadarını al”), fıkıhta “zafer meselesi” denen bir tartışmanın da kaynağıdır: Hakkını alamayan bir kişi, borçlunun malından izni olmadan hakkı kadarını alabilir mi? Şâfiîler ve bazı Hanbelîler bu hadise dayanarak buna izin verir. Hanefîler belirli şartlarla, Mâlikîler ise daha sınırlı olarak kabul eder. Bu, bir aile hadisinin genel borçlar hukukunu nasıl etkilediğini gösterir.",
        tedebbur: [["Hind hadisinden “hakkını alamayan kişi onu izinsiz alabilir” gibi genel bir kural çıkarmak sence doğru mu? Bu kuralın tehlikeleri neler olabilir?", "Hakkın açık olup olmamasını ve kişinin kendi davasında hâkim olmasının risklerini düşün."], ["Nafakanın “sıla” mı “ivaz” mı olduğu sorusu hangi pratik sonuçları doğuruyor?", "Geçmiş nafakanın düşüp düşmemesini ve nafakasızlık hâlinde ayrılık hakkını düşün."]] },
      4: { amac: "Örfün hükmü nasıl etkilediğini kavramak.", odak: "Örf değişince hüküm değişir mi?",
        not: "Karâfî, el-Furûk'ta şöyle der: “Nakledilen ifadelere donup kalmak, dinde bir sapma ve Müslüman âlimlerin ve geçmiş selefin maksatlarını bilmemektir.” Ona göre bir müftü, başka bir beldeden gelen birine fetva verirken, kendi beldesinin örfüne göre değil, o kişinin beldesinin örfüne göre fetva vermelidir. Bu, örfün yalnızca zamana değil, mekâna göre de değiştiğini gösterir.",
        tedebbur: [["Karâfî'nin “donup kalmak” eleştirisi, eski fıkıh kitaplarını okuma şeklimizi nasıl değiştirmeli?", "Bir hükmün dayandığı örfü tespit etmenin ve bugünkü örfle karşılaştırmanın önemini düşün."], ["Örfün aile hukukundaki gücü nerede sınırlanmalı? Hangi hükümler örfe bırakılamaz?", "Bir nasla açıkça belirlenmiş hükümler ile örfe bırakılmış hükümleri ayırt et."]] },
      5: { amac: "Azınlık görüşünün kanunlaşmasını bir aile meselesinde görmek.", odak: "Tek mecliste verilen üç talak kaç talak sayılır?",
        not: "Bu meselede bir ayrıntı daha önemlidir: Kocanın “Seni üç talakla boşadım” demesi ile “Boşsun, boşsun, boşsun” diye aynı sözü tekrarlaması aynı şey değildir. Şâfiî ve Hanbelî fakihlerine göre ikinci durumda koca, ilk sözü pekiştirmeyi (te'kîd) kastettiğini söylerse ve bu niyet inandırıcıysa, tek talak sayılabilir. Bu, cumhurun bile, talak sayısını belirlerken lafzın yanında kişinin niyetini dikkate aldığını gösterir.",
        tedebbur: [["Bir azınlık görüşünün kanunlaşması, aile içindeki somut bir sorunu (aceleyle verilen ve pişman olunan talak) nasıl çözüyor? Bu çözümün bir bedeli var mı?", "Ailenin korunması ile dört mezhebin ittifakına bağlılık arasındaki gerilimi düşün."], ["Hz. Ömer'in uygulamasının bir icmâ mı yoksa bir siyaset tedbiri mi olduğu sorusu, bu kanunlaşmanın meşruiyetini nasıl etkiler?", "Her iki nitelemenin sonuçlarını karşılaştır."]] },
      6: { amac: "Hükmün gerekçesini aile ve yargı bağlamında tartışmak.", odak: "Kadının şahitliğine dair âyet bir ispat kuralı mı, bir ihtiyat tavsiyesi mi?",
        not: "Şahitlik (şehâdet) ile rivayet arasında önemli bir fark vardır. Hadis rivayetinde kadının sözü erkeğinkiyle eşit kabul edilir; Hz. Âişe sahabenin en çok başvurduğu fıkıh ve hadis otoritelerinden biridir. Zehebî, ravileri eleştirdiği Mîzânü'l-i'tidâl'in kadınlar bölümünde, kadın raviler arasında hadis uydurmakla itham edilmiş veya rivayeti terk edilmiş birini bilmediğini söyler. Dinin en temel kaynağının aktarımında eşit kabul edilen bir sözün, bir borç senedindeki şahitlikte farklı değerlendirilmesi, bu hükmün kadının güvenilirliğine değil, başka bir gerekçeye dayandığını düşündürür.",
        tedebbur: [["“İşhâd” ile “beyyine” arasındaki ayrım, âyetin anlaşılmasını nasıl değiştirir?", "Bir sözleşmeyi önceden belgelendirmek ile bir davada delil sunmak arasındaki farkı düşün."], ["Kadının şahitliği meselesinde hangi yorumu daha ikna edici buluyorsun ve neden?", "Klasik cumhurun, İbnü'l-Kayyim'in ve Muhammed Abduh'un yorumlarını karşılaştır."]] },
      7: { amac: "Mezhepler arası tercihin meşruiyetini ve sınırlarını öğrenmek.", odak: "Bir mezhepten diğerine geçmek ne zaman meşrudur?",
        not: "Abdülvehhâb eş-Şa'rânî, el-Mîzânü'l-kübrâ'da mezheplerin farklı görüşlerinin şeriatın iki mertebesine karşılık geldiğini savunur: azîmet (sıkı olan) ve ruhsat (kolay olan). Ona göre güçlü olan azîmetle, zayıf olan ruhsatla amel eder; böylece bütün mezhepler, farklı durumdaki insanlar için şeriatın birer yolu olur. Bu yaklaşım, mezhepler arası tercihe bir teorik zemin sunar.",
        tedebbur: [["Şa'rânî'nin “azîmet ve ruhsat” teorisi, mezhepler arası tercihi bir zaaf olmaktan çıkarıp neye dönüştürüyor?", "Farklı görüşlerin farklı insanların durumuna göre birer yol olabileceğini düşün."], ["Telfîk ile ruhsat avcılığını birbirinden nasıl ayırırsın?", "Tercihin bir ihtiyaca mı, yoksa nefsin arzusuna mı dayandığını ölçü al."]] },
      8: { amac: "Ailenin genişlemesiyle gelen hükümleri öğrenmek.", odak: "Doğumla ilgili sünnetlerden hangilerinin dayanağı sahih, hangilerininki zayıftır?",
        not: "Hanefîlerin akîkayı sünnet-i müekkede değil mubah veya müstehab sayması, akîkanın kurban ibadetiyle neshedildiği görüşüne dayanır. Bu görüşe göre İslâm'ın ilk döneminde akîka yaygındı; kurban meşru kılınınca akîkanın hükmü gevşedi. Cumhur ise akîka hadislerinin sahih olduğunu ve neshe dair bir delil bulunmadığını söyler. Bu, “nesih” iddiasının hükümleri nasıl etkilediğinin bir örneğidir.",
        tedebbur: [["Bir sünnetin dayanağının zayıf olması, onunla amel etmeyi tamamen bırakmayı mı gerektirir?", "Âlimlerin, zayıf bir rivayete dayanan ama manası güzel olan uygulamaları (doğumda ezan gibi) nasıl değerlendirdiğini düşün."], ["Bir çocuğun doğumunda yapılan sünnetler, ona ve aileye ne tür bir anlam ve kimlik kazandırır?", "İsim koymanın, tahnîkin ve akîkanın sembolik anlamlarını düşün."]] }
    },
    sentez: "Velî şartı, nafaka ve kefâet meselelerinden birini seç. Hanefî görüş ile cumhur görüşünü tabloya dök: dayandıkları âyet ve hadis, usul gerekçesi ve pratik sonuçları. Sonra bugünün aile hayatında hangisinin daha adil sonuç verdiğini düşündüğünü gerekçeleriyle yaz." }
};
